window.ETSDATA=window.ETSDATA||{};window.ETSDATA[7]={"lc":{"p1":[{"n":1,"opts":["She’s holding a water bottle.","She’s looking at a newspaper.","She’s reaching for a book.","She’s standing next to a copier."],"vi":["Cô ấy đang cầm một chai nước.","Cô ấy đang nhìn một tờ báo.","Cô ấy đang với tay lấy một cuốn sách.","Cô ấy đang đứng cạnh một máy photocopy."],"ans":"B","a":"E26-T07-01.mp3","img":"q1.jpg"},{"n":2,"opts":["A tire is leaning against a car.","A chain has been left on the ground.","A car is backing out of a garage.","A box of tools has been set on top of a car."],"vi":["Một chiếc lốp xe đang tựa vào ô tô.","Một sợi dây xích đã được để lại trên mặt đất.","Một chiếc ô tô đang lùi ra khỏi gara.","Một hộp dụng cụ đã được đặt trên nóc ô tô."],"ans":"A","a":"E26-T07-02.mp3","img":"q2.jpg"},{"n":3,"opts":["He’s pushing a cart toward a doorway.","He’s spraying cleaning liquid onto a glass door.","He’s mopping up a tiled floor.","He’s setting up a bulletin board."],"vi":["Anh ấy đang đẩy một chiếc xe đẩy về phía cửa ra vào.","Anh ấy đang xịt nước tẩy rửa lên cửa kính.","Anh ấy đang lau sàn lát gạch.","Anh ấy đang lắp đặt một bảng thông báo."],"ans":"A","a":"E26-T07-03.mp3","img":"q3.jpg"},{"n":4,"opts":["The woman is walking across the street.","The woman is repairing a bicycle.","The woman is wearing a helmet.","The woman is getting into a vehicle."],"vi":["Người phụ nữ đang đi bộ băng qua đường.","Người phụ nữ đang sửa xe đạp.","Người phụ nữ đang đội mũ bảo hiểm.","Người phụ nữ đang bước vào một phương tiện giao thông."],"ans":"C","a":"E26-T07-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some umbrellas have been opened in an outdoor dining area.","All the tables are occupied by diners.","A worker is sweeping a dining area.","Flowers have been placed on the tables."],"vi":["Một số chiếc ô đã được mở ở khu vực ăn uống ngoài trời.","Tất cả các bàn đều đã có thực khách ngồi.","Một công nhân đang quét dọn khu vực ăn uống.","Hoa đã được đặt trên bàn."],"ans":"A","a":"E26-T07-05.mp3","img":"q5.jpg"},{"n":6,"opts":["File folders have been arranged on a shelf.","Some window blinds have been raised.","Some waste baskets have been turned upside down.","An office chair has been pushed under a desk."],"vi":["Các bìa hồ sơ đã được sắp xếp trên kệ.","Một số rèm cửa sổ đã được kéo lên.","Một số giỏ rác đã bị lật ngược.","Một chiếc ghế văn phòng đã được đẩy vào dưới bàn làm việc."],"ans":"D","a":"E26-T07-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Where do I sign this contract?","qvi":"Tôi ký hợp đồng này ở đâu?","opts":["A large account.","Here at the bottom.","Hang it on the wall."],"vi":["Một tài khoản lớn.","Ở đây, phía dưới cùng.","Treo nó lên tường."],"ans":"B","a":"E26-T07-07.mp3"},{"n":8,"q":"How about planting a vegetable garden?","qvi":"Hay là chúng ta trồng một vườn rau nhỉ?","opts":["There’s parking available on the next street.","I think that’s a good idea.","A new hardware store."],"vi":["Có chỗ đậu xe ở con phố tiếp theo.","Tôi nghĩ đó là một ý tưởng hay.","Một cửa hàng ngũ kim mới."],"ans":"B","a":"E26-T07-08.mp3"},{"n":9,"q":"When did the conference committee meeting get canceled?","qvi":"Cuộc họp ủy ban hội nghị đã bị hủy khi nào?","opts":["Yesterday morning.","A new member.","At the hotel on Main Street."],"vi":["Sáng hôm qua.","Một thành viên mới.","Tại khách sạn trên phố Main."],"ans":"A","a":"E26-T07-09.mp3"},{"n":10,"q":"Does the company pay for our hotel rooms?","qvi":"Công ty có chi trả tiền phòng khách sạn cho chúng ta không?","opts":["I have a layover in Dubai.","No, we have to pay for them ourselves.","That’s my favorite airline."],"vi":["Tôi có một điểm dừng chân tại Dubai.","Không, chúng ta phải tự thanh toán.","Đó là hãng hàng không yêu thích của tôi."],"ans":"B","a":"E26-T07-10.mp3"},{"n":11,"q":"Our team’s going to inspect the construction site tomorrow.","qvi":"Đội của chúng ta sẽ đi kiểm tra công trường vào ngày mai.","opts":["His name is Alberto.","The office down the hall.","That’s the first I’ve heard of it."],"vi":["Tên anh ấy là Alberto.","Văn phòng ở phía cuối hành lang.","Đây là lần đầu tiên tôi nghe về việc đó."],"ans":"C","a":"E26-T07-11.mp3"},{"n":12,"q":"Why does the Moon look so close in this photograph?","qvi":"Tại sao Mặt Trăng trông lại gần như vậy trong bức ảnh này?","opts":["Are there seats available for the astronomy presentation?","Because I used a special camera lens.","She’s always wanted to be an astronaut."],"vi":["Còn chỗ ngồi cho buổi thuyết trình về thiên văn học không?","Bởi vì tôi đã sử dụng một ống kính máy ảnh đặc biệt.","Cô ấy luôn muốn trở thành một phi hành gia."],"ans":"B","a":"E26-T07-12.mp3"},{"n":13,"q":"How do I log on to this computer?","qvi":"Làm thế nào để tôi đăng nhập vào máy tính này?","opts":["Some printer ink and paper.","I’ll send you a temporary password.","No, he was late."],"vi":["Một ít mực in và giấy.","Tôi sẽ gửi cho bạn một mật khẩu tạm thời.","Không, anh ấy đã đến muộn."],"ans":"B","a":"E26-T07-13.mp3"},{"n":14,"q":"When does the property manager arrive?","qvi":"Khi nào quản lý bất động sản sẽ đến?","opts":["On Whitmer Boulevard.","You’re right, it doesn’t fit.","At ten o’clock."],"vi":["Trên đại lộ Whitmer.","Bạn nói đúng, nó không vừa.","Vào lúc mười giờ."],"ans":"C","a":"E26-T07-14.mp3"},{"n":15,"q":"Let’s have dinner at the French restaurant tonight.","qvi":"Tối nay chúng ta hãy đi ăn tối ở nhà hàng Pháp nhé.","opts":["OK, I’ll see you there.","I’d like to buy some new cookware.","Here’s a copy of the agreement."],"vi":["Được, tôi sẽ gặp bạn ở đó.","Tôi muốn mua một vài dụng cụ nấu ăn mới.","Đây là bản sao của bản thỏa thuận."],"ans":"A","a":"E26-T07-15.mp3"},{"n":16,"q":"Who’s supervising the production line?","qvi":"Ai đang giám sát dây chuyền sản xuất?","opts":["Please sign on the line.","Luca’s doing it.","A 45-minute lunch break."],"vi":["Vui lòng ký vào dòng này.","Luca đang làm việc đó.","Nghỉ trưa 45 phút."],"ans":"B","a":"E26-T07-16.mp3"},{"n":17,"q":"When will the reception for the artists start?","qvi":"Khi nào buổi tiếp đón dành cho các nghệ sĩ sẽ bắt đầu?","opts":["After the lecture.","Asian art.","At the conference center."],"vi":["Sau buổi thuyết giảng.","Nghệ thuật châu Á.","Tại trung tâm hội nghị."],"ans":"A","a":"E26-T07-17.mp3"},{"n":18,"q":"How often should I submit my travel expenses?","qvi":"Tôi nên nộp chi phí đi lại của mình bao lâu một lần?","opts":["Sure, I’ll trim the branches a little.","Once a month.","An updated owner’s manual."],"vi":["Được thôi, tôi sẽ cắt tỉa các cành một chút.","Mỗi tháng một lần.","Sách hướng dẫn sử dụng đã được cập nhật."],"ans":"B","a":"E26-T07-18.mp3"},{"n":19,"q":"Our print shop is going to have a sale on shirts.","qvi":"Hiệu in ấn của chúng tôi sắp có chương trình giảm giá áo thun.","opts":["I'm afraid I have no more change.","It's his favorite television show.","OK—when will it start?"],"vi":["Tôi e là tôi không còn tiền lẻ nữa.","Đó là chương trình truyền hình yêu thích của anh ấy.","Được thôi—khi nào nó bắt đầu?"],"ans":"C","a":"E26-T07-19.mp3"},{"n":20,"q":"You already bought a new part for the sprinkler system, right?","qvi":"Bạn đã mua một bộ phận mới cho hệ thống phun nước rồi, đúng không?","opts":["Check the weather forecast.","Yes, I did that last week.","That flight departs soon."],"vi":["Kiểm tra dự báo thời tiết.","Vâng, tôi đã làm việc đó vào tuần trước.","Chuyến bay đó sắp khởi hành."],"ans":"B","a":"E26-T07-20.mp3"},{"n":21,"q":"How many lamps are made at the factory every day?","qvi":"Hằng ngày có bao nhiêu đèn được sản xuất tại nhà máy?","opts":["Some new machinery.","A new line of men's clothing.","About 500."],"vi":["Một số máy móc mới.","Một dòng quần áo nam mới.","Khoảng 500."],"ans":"C","a":"E26-T07-21.mp3"},{"n":22,"q":"Are you going out to eat, or did you bring your lunch from home?","qvi":"Bạn sẽ đi ăn ngoài hay đã mang cơm từ nhà?","opts":["Right next to my office.","That'll be five dollars, please.","It's in the microwave."],"vi":["Ngay cạnh văn phòng của tôi.","Là năm đô la, làm ơn.","Nó ở trong lò vi sóng."],"ans":"C","a":"E26-T07-22.mp3"},{"n":23,"q":"Can I place an order online?","qvi":"Tôi có thể đặt hàng trực tuyến không?","opts":["The post office on Main Street.","Our Web site is currently down for maintenance.","No, he put it in the filing cabinet."],"vi":["Bưu điện trên phố Main.","Trang web của chúng tôi hiện đang bảo trì.","Không, anh ấy đã đặt nó trong tủ hồ sơ."],"ans":"B","a":"E26-T07-23.mp3"},{"n":24,"q":"Shouldn't the new floor plan be finished today?","qvi":"Liệu sơ đồ mặt bằng mới có nên hoàn thành hôm nay không?","opts":["I enjoyed the movie.","My team is short-staffed right now.","We met in the cafeteria."],"vi":["Tôi thích bộ phim.","Nhóm của tôi hiện đang thiếu nhân sự.","Chúng tôi đã gặp nhau ở nhà ăn."],"ans":"B","a":"E26-T07-24.mp3"},{"n":25,"q":"Who's the new head of the legal department?","qvi":"Ai là trưởng phòng pháp chế mới?","opts":["No, I think it's on the second floor.","It hasn't been announced yet.","Thanks, that'll help."],"vi":["Không, tôi nghĩ nó ở tầng hai.","Chưa được công bố.","Cảm ơn, điều đó sẽ giúp ích."],"ans":"B","a":"E26-T07-25.mp3"},{"n":26,"q":"Who's scheduled to repair the water heater in building two?","qvi":"Ai được lên lịch để sửa bình nóng lạnh trong tòa nhà số hai?","opts":["There's a bottle of water in the refrigerator.","Twenty dollars each.","That job was completed yesterday."],"vi":["Có một chai nước trong tủ lạnh.","Hai mươi đô la mỗi người.","Công việc đó đã được hoàn thành hôm qua."],"ans":"C","a":"E26-T07-26.mp3"},{"n":27,"q":"Why were the sales figures so high last quarter?","qvi":"Tại sao doanh số bán hàng lại cao như vậy trong quý vừa rồi?","opts":["I think that the storefront is vacant.","Koji is in charge of analyzing market trends.","Let me unlock the door first."],"vi":["Tôi nghĩ cửa hàng đang trống.","Koji phụ trách phân tích xu hướng thị trường.","Để tôi mở khóa cửa trước."],"ans":"B","a":"E26-T07-27.mp3"},{"n":28,"q":"Ms. Martin is demonstrating the new software at the conference.","qvi":"Cô Martin đang trình diễn phần mềm mới tại hội nghị.","opts":["I live on Vine Street.","No, they catered food last year.","I thought she was on vacation."],"vi":["Tôi sống trên đường Vine.","Không, năm ngoái họ đã cung cấp dịch vụ ăn uống.","Tôi tưởng cô ấy đang nghỉ phép."],"ans":"C","a":"E26-T07-28.mp3"},{"n":29,"q":"Let's hire Johnson Construction to fix this roof.","qvi":"Hãy thuê công ty xây dựng Johnson để sửa mái nhà này.","opts":["They don't seem to be.","They can't start until next month.","I think it's on the bottom shelf."],"vi":["Họ dường như không phải.","Họ không thể bắt đầu cho đến tháng tới.","Tôi nghĩ nó ở kệ dưới cùng."],"ans":"B","a":"E26-T07-29.mp3"},{"n":30,"q":"Your travel itinerary says you're going to Seattle, right?","qvi":"Lịch trình chuyến đi của bạn nói rằng bạn sẽ đến Seattle, đúng không?","opts":["But I'm going to London.","Turn left at the light, please.","An e-mail update."],"vi":["Nhưng tôi sẽ đến London.","Rẽ trái tại đèn giao thông, làm ơn.","Một bản cập nhật qua email."],"ans":"A","a":"E26-T07-30.mp3"},{"n":31,"q":"Won't theater tickets become available later today?","qvi":"Vé xem kịch sẽ có sẵn sau vào hôm nay chứ?","opts":["A new pair of work boots.","It should say on their Web site.","Yes, I saw him at the convention."],"vi":["Một đôi giày bảo hộ mới.","Trên trang web của họ sẽ nói rõ.","Vâng, tôi đã thấy anh ấy tại hội nghị."],"ans":"B","a":"E26-T07-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","Carmen, I don't know if you realize it, but your office chair makes a squeaking sound every time you move. It's a little distracting when the office is so quiet.","Carmen, không biết cô có nhận ra không, nhưng mỗi lần cô di chuyển thì ghế văn phòng của cô lại phát ra tiếng kêu cót két. Khi văn phòng yên tĩnh thì hơi bị làm phiền đấy."],["W","Oh! I had my headset on, so I didn't realize that. I'll go swap this chair with one from the conference room.","Ồ! Tôi đang đeo tai nghe nên không nhận ra. Tôi sẽ đi đổi ghế này lấy một cái ở phòng họp."],["M","Thanks for understanding. And don't forget that our team is ordering takeout from a Thai restaurant for lunch. Do you want anything?","Cảm ơn cô đã thông cảm. Và đừng quên là đội mình đang đặt đồ ăn Thái mang về cho bữa trưa nhé. Cô muốn ăn gì không?"],["W","Sure. I'd love some spring rolls!","Có chứ. Tôi muốn ăn chả giò!"]],"qs":[{"n":32,"q":"What complaint does the man make?","qvi":"Người đàn ông phàn nàn điều gì?","opts":["A room is too small.","A noise is distracting.","Some software is slow.","A printer is broken."],"vi":["Phòng quá nhỏ.","Có tiếng ồn gây mất tập trung.","Phần mềm chạy chậm.","Máy in bị hỏng."],"ans":"B"},{"n":33,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Change her chair","Borrow a computer laptop","Contact the help desk","Work from home"],"vi":["Đổi ghế.","Mượn một chiếc laptop.","Liên hệ bộ phận hỗ trợ kỹ thuật.","Làm việc tại nhà."],"ans":"A"},{"n":34,"q":"What does the man remind the woman about?","qvi":"Người đàn ông nhắc người phụ nữ về điều gì?","opts":["A team lunch","A training session","A project deadline","A policy change"],"vi":["Bữa trưa của nhóm.","Buổi đào tạo.","Hạn chót dự án.","Sự thay đổi chính sách."],"ans":"A"}],"a":"E26-T07-32-34.mp3"},{"ns":[35,37],"script":[["M","Amina, do you have a few minutes? I finished preparing the sample dish that you asked for. You can try it now if you'd like.","Amina, cô có ít phút không? Tôi đã làm xong món mẫu mà cô yêu cầu. Cô muốn thử ngay bây giờ không?"],["W","Sure, I have time now. I think the pasta is delicious. I like the hint of fresh lemon flavor. It'll make a great addition to our summer menu.","Được, giờ tôi rảnh. Tôi thấy món pasta ngon lắm. Tôi thích chút hương chanh tươi nhẹ nhàng này. Nó sẽ là một bổ sung tuyệt vời cho thực đơn mùa hè của chúng ta."],["M","I agree. But we don't use lemons in any other dish. Should I get in touch with our fruit and vegetable supplier?","Tôi đồng ý. Nhưng chúng ta không dùng chanh trong món nào khác. Tôi có nên liên lạc với nhà cung cấp rau củ quả không?"],["W","Thanks. Just ask him what the cost difference would be if we added five kilograms of lemons to our regular delivery.","Cảm ơn. Chỉ cần hỏi ông ấy nếu thêm năm kilogram chanh vào đơn hàng định kỳ thì chi phí chênh lệch bao nhiêu thôi."]],"qs":[{"n":35,"q":"What most likely is the man’s occupation?","qvi":"Công việc của người đàn ông có khả năng là gì?","opts":["Server","Chef","Farmer","Food critic"],"vi":["Nhân viên phục vụ.","Đầu bếp.","Nông dân.","Nhà phê bình ẩm thực."],"ans":"B"},{"n":36,"q":"What does the woman say she likes?","qvi":"Người phụ nữ nói cô ấy thích điều gì?","opts":["The design of a menu","The business hours of a restaurant","The flavor of a dish","The color of some tablecloths"],"vi":["Thiết kế của thực đơn.","Giờ hoạt động của nhà hàng.","Hương vị của món ăn.","Màu của khăn trải bàn."],"ans":"C"},{"n":37,"q":"Why is the man going to make a phone call?","qvi":"Tại sao người đàn ông gọi điện?","opts":["To inquire about a job","To consult a colleague","To change a delivery date","To ask about a cost"],"vi":["Hỏi về việc làm.","Tham khảo ý kiến đồng nghiệp.","Thay đổi ngày giao hàng.","Hỏi về chi phí."],"ans":"D"}],"a":"E26-T07-35-37.mp3"},{"ns":[38,40],"script":[["M","Dr. Ruiz, do you have a minute?","Bác sĩ Ruiz, ngài có chút thời gian không?"],["W","Sure.","Có."],["M","It looks like the hospital has a little money left over in our staff development budget. Can you think of anything we could spend it on? I'm just looking for ideas.","Hình như bệnh viện còn dư một ít tiền trong ngân sách phát triển nhân viên. Ngài có nghĩ ra thứ gì để chi tiêu không? Tôi chỉ đang tìm ý tưởng thôi."],["W","Well, I'd love it if we could get a subscription to Prescriber Med's newsletter. A lot of the expert summaries in it are useful for my clinical practice work.","Ừm, tôi rất muốn chúng ta đăng ký nhận bản tin của Prescriber Med. Có rất nhiều tóm tắt chuyên gia trong đó hữu ích cho công việc lâm sàng của tôi."],["M","Sounds good. I'm going to ask other doctors, too, and see how best to use these funds.","Nghe hay đấy. Tôi cũng sẽ hỏi các bác sĩ khác để xem cách sử dụng quỹ này tốt nhất."],["W","Great. I'd suggest maybe sending out a survey, though. That'd be more convenient.","Tuyệt. Nhưng tôi đề nghị gửi một cuộc khảo sát đi. Như vậy sẽ tiện hơn."],["M","Good idea! I'll do that.","Ý hay! Tôi sẽ làm thế."]],"qs":[{"n":38,"q":"Where do the speakers most likely work?","qvi":"Hai người có khả năng làm việc ở đâu?","opts":["At a hospital","At a law firm","At an accounting company","At a publishing headquarters"],"vi":["Bệnh viện","Văn phòng luật","Công ty kế toán","Trụ sở nhà xuất bản"],"ans":"A"},{"n":39,"q":"What does the woman request?","qvi":"Người phụ nữ yêu cầu gì?","opts":["A newsletter subscription","A parking pass","Budget data","Staff biographies"],"vi":["Đăng ký nhận bản tin","Thẻ đậu xe","Dữ liệu ngân sách","Tiểu sử nhân viên"],"ans":"A"},{"n":40,"q":"What does the woman suggest the man do?","qvi":"Người phụ nữ gợi ý người đàn ông làm gì?","opts":["Call a coworker","Ask for an extension","Send out a survey","Request overtime hours"],"vi":["Gọi cho một đồng nghiệp","Xin gia hạn","Gửi khảo sát","Đăng ký làm thêm giờ"],"ans":"C"}],"a":"E26-T07-38-40.mp3"},{"ns":[41,43],"script":[["M","Hello, I just received a pair of shoes I ordered from your online store. They're nice, but they don't fit. Can I ship them back to you for a refund?","Xin chào, tôi vừa nhận được đôi giày đặt từ cửa hàng trực tuyến của quý công ty. Đẹp đấy nhưng không vừa chân. Tôi có thể gửi trả lại để được hoàn tiền không?"],["W","Yes. But for a refund, I'm afraid you'll have to ship the shoes back at your own expense. On the other hand, if you'd like to exchange them, we'll send you a return label for free.","Có ạ. Nhưng để hoàn tiền thì rất tiếc khách hàng phải tự chịu phí gửi trả. Ngược lại, nếu anh muốn đổi thì chúng tôi sẽ gửi nhãn trả hàng miễn phí."],["M","In that case, I'll exchange them for another size. How do I do that?","Vậy thì tôi đổi sang kích cỡ khác. Làm thế nào ạ?"],["W","I'll e-mail you a link. Just click on it, and you'll be redirected to the instructions for exchanges on our Web site.","Tôi sẽ gửi email cho anh một đường link. Anh chỉ cần nhấp vào là sẽ được chuyển đến trang hướng dẫn đổi hàng trên website của chúng tôi."]],"qs":[{"n":41,"q":"What type of business is the man calling?","qvi":"Người đàn ông đang gọi đến loại hình doanh nghiệp nào?","opts":["A shoe company","A marketing agency","A shipping company","A tailor shop"],"vi":["Công ty giày","Công ty marketing","Công ty vận chuyển","Tiệm may"],"ans":"A"},{"n":42,"q":"What does the man decide to do?","qvi":"Người đàn ông quyết định làm gì?","opts":["Contact a different business","Exchange some merchandise","Write an online review","Download a catalog"],"vi":["Liên hệ doanh nghiệp khác","Đổi hàng","Viết đánh giá trực tuyến","Tải danh mục sản phẩm"],"ans":"B"},{"n":43,"q":"What will the woman send by e-mail?","qvi":"Người phụ nữ sẽ gửi gì qua email?","opts":["Some design images","A sales receipt","Some delivery options","A Web site link"],"vi":["Một số hình ảnh thiết kế","Hóa đơn bán hàng","Một số tùy chọn giao hàng","Liên kết trang web"],"ans":"D"}],"a":"E26-T07-41-43.mp3"},{"ns":[44,46],"script":[["M","On today's podcast, we have Gabriela Espinoza, a former history professor who focuses on ancient civilizations. Recently, however, she left the university for another position—tell us about that.","Trong podcast hôm nay, chúng ta có Gabriela Espinoza, một cựu giáo sư lịch sử chuyên về các nền văn minh cổ đại. Gần đây cô ấy đã rời trường đại học để làm công việc khác – xin kể về điều đó."],["W","Well, last year, a film company was producing a movie about the famous pyramids at Giza. They needed an expert in ancient Egypt, and they found me. Now I work full-time as a consultant for the film industry.","À, năm ngoái một hãng phim đang sản xuất phim về các kim tự tháp nổi tiếng ở Giza. Họ cần chuyên gia về Ai Cập cổ đại và đã tìm được tôi. Giờ tôi làm cố vấn toàn thời gian cho ngành công nghiệp phim."],["M","Do you actually work on set?","Cô có thực sự làm việc tại phim trường không?"],["W","Yes. When there are last-minute changes, I make sure the changes are historically accurate. In fact, I'll be in Egypt next week, sailing down the Nile River.","Có. Khi có thay đổi phút chót, tôi đảm bảo những thay đổi đó chính xác về mặt lịch sử. Thực ra tuần tới tôi sẽ ở Ai Cập, đi thuyền dọc sông Nile."]],"qs":[{"n":44,"q":"What is the woman’s area of expertise?","qvi":"Lĩnh vực chuyên môn của người phụ nữ là gì?","opts":["Music","Biology","History","Mathematics"],"vi":["Âm nhạc","Sinh học","Lịch sử","Toán học"],"ans":"C"},{"n":45,"q":"What is the woman’s current job?","qvi":"Công việc hiện tại của người phụ nữ là gì?","opts":["A recruiter for universities","A curator for museums","A consultant for film studios","An editor for publishing companies"],"vi":["Người tuyển sinh cho các trường đại học","Người quản lý bảo tàng","Cố vấn cho các hãng phim","Biên tập viên cho các công ty xuất bản"],"ans":"C"},{"n":46,"q":"What will the woman do next week?","qvi":"Tuần tới người phụ nữ sẽ làm gì?","opts":["Promote her new book","Audition for a movie","Teach a seminar","Visit another country"],"vi":["Quảng bá cuốn sách mới","Thử vai cho một bộ phim","Giảng dạy hội thảo","Du lịch nước ngoài"],"ans":"D"}],"a":"E26-T07-44-46.mp3"},{"ns":[47,49],"script":[["W","Pedro, I just registered for the national marketing convention in June.","Pedro, tôi vừa đăng ký hội nghị marketing toàn quốc tháng Sáu rồi."],["M","Me, too. And I printed out the program with all the talks and workshops.","Tôi cũng vậy. Tôi còn in chương trình có tất cả các buổi nói chuyện và hội thảo nữa."],["W","Oh, can I take a look? This is great! It looks like there are plenty of breaks in the schedule for networking with potential clients.","Ồ, cho tôi xem với? Tuyệt quá! Có vẻ lịch trình có nhiều khoảng nghỉ để kết nối với khách hàng tiềm năng."],["M","Right. So don't forget to bring your business cards with you. You'll need a lot of them.","Đúng rồi. Thế nên đừng quên mang danh thiếp theo nhé. Em sẽ cần nhiều lắm đấy."],["W","Thanks for the reminder. I'd better order more.","Cảm ơn anh nhắc. Em phải đặt in thêm thôi."]],"qs":[{"n":47,"q":"What are the speakers preparing for in June?","qvi":"Hai người đang chuẩn bị cho sự kiện gì vào tháng Sáu?","opts":["A company merger","A fund-raising event","An industry convention","A product launch"],"vi":["Sáp nhập công ty","Sự kiện gây quỹ","Hội nghị ngành","Ra mắt sản phẩm"],"ans":"C"},{"n":48,"q":"Why is the woman pleased?","qvi":"Vì sao người phụ nữ vui mừng?","opts":["She has been promoted to manager.","She will have networking opportunities.","An advertising campaign was successful.","An article about the company is positive."],"vi":["Cô ấy được thăng chức quản lý.","Cô ấy sẽ có cơ hội kết nối.","Chiến dịch quảng cáo thành công.","Có bài báo tích cực về công ty."],"ans":"B"},{"n":49,"q":"What does the man remind the woman about?","qvi":"Người đàn ông nhắc người phụ nữ về điều gì?","opts":["Bringing business cards","Compiling a guest list","Reviewing a contract","Submitting receipts"],"vi":["Mang theo danh thiếp","Chuẩn bị danh sách khách","Xem lại hợp đồng","Nộp biên lai"],"ans":"A"}],"a":"E26-T07-47-49.mp3"},{"ns":[50,52],"script":[["M1","We need to come up with a new menu design for our seaside restaurant. Something memorable. Do you two have any suggestions?","Chúng ta cần nghĩ ra thiết kế menu mới cho nhà hàng ven biển của chúng ta. Cái gì đó đáng nhớ. Hai người có gợi ý gì không?"],["M2","Maybe we could use a dolphin jumping out of the water. Junko, what do you think?","Có lẽ chúng ta có thể dùng hình cá heo nhảy ra khỏi mặt nước. Junko, chị nghĩ sao?"],["W","Oh, I really like that idea! And it's fitting, since our restaurant is at the beach. Minoru, can you put together a graphic for the rest of us to look at?","Ồ, em rất thích ý tưởng đó! Và nó phù hợp, vì nhà hàng của chúng ta ở bãi biển. Minoru, anh có thể làm một graphic để mọi người xem không?"],["M2","I'll start working on it immediately.","Tôi sẽ bắt đầu ngay lập tức."],["M1","Great. Hopefully, we can finalize something before next month's community fair.","Tốt. Hy vọng chúng ta có thể hoàn tất trước hội chợ cộng đồng tháng tới."]],"qs":[{"n":50,"q":"Who most likely are the speakers?","qvi":"Hai người có khả năng là ai?","opts":["Tour guides","Hotel managers","Marine biologists","Business owners"],"vi":["Hướng dẫn viên du lịch","Quản lý khách sạn","Nhà sinh vật biển","Chủ doanh nghiệp"],"ans":"D"},{"n":51,"q":"What is Minoru asked to do?","qvi":"Minoru được yêu cầu làm gì?","opts":["Confirm a reservation","Create a logo","Print some documents","Review some résumés"],"vi":["Xác nhận đặt chỗ","Tạo logo","In tài liệu","Xem xét hồ sơ xin việc"],"ans":"B"},{"n":52,"q":"What event is taking place next month?","qvi":"Sự kiện nào sẽ diễn ra vào tháng tới?","opts":["A seasonal sale","A trade show","A community fair","A company picnic"],"vi":["Khuyến mãi theo mùa","Hội chợ thương mại","Hội chợ cộng đồng","Tiệc công ty"],"ans":"C"}],"a":"E26-T07-50-52.mp3"},{"ns":[53,55],"script":[["M","Hello. Welcome to Henderson State Park. Parking is free this weekend.","Xin chào. Chào mừng đến với Công viên Bang Henderson. Cuối tuần này đỗ xe miễn phí."],["W","That's great! I'm visiting here for the first time. Do you have a map of the park trails?","Tốt quá! Tôi đến đây lần đầu. Anh có bản đồ đường mòn công viên không?"],["M","I'm sorry. I just ran out of maps. It's been a very busy weekend.","Xin lỗi. Tôi vừa hết bản đồ. Cuối tuần này rất bận rộn."],["W","Well, I'm just a little concerned since I don't know the trails.","Ừm, tôi hơi lo vì không biết đường mòn."],["M","I understand. The visitor center is about 400 meters up the road.","Tôi hiểu. Trung tâm du khách cách khoảng 400 mét lên đường."],["W","Oh, that's good to know. Thanks.","Ồ, tốt khi biết vậy. Cảm ơn."]],"qs":[{"n":53,"q":"Where is the conversation taking place?","qvi":"Cuộc trò chuyện diễn ra ở đâu?","opts":["At a bus station","At a city museum","At a state park","At a sports stadium"],"vi":["Trạm xe buýt","Bảo tàng thành phố","Công viên tiểu bang","Sân vận động"],"ans":"C"},{"n":54,"q":"Why does the woman say she is concerned?","qvi":"Tại sao người phụ nữ nói cô ấy lo lắng?","opts":["She is late for an appointment.","She does not have a credit card.","She did not reserve tickets.","She is unfamiliar with a location."],"vi":["Cô ấy trễ hẹn.","Cô ấy không có thẻ tín dụng.","Cô ấy chưa đặt vé.","Cô ấy không quen khu vực."],"ans":"D"},{"n":55,"q":"Why does the man say, “The visitor center is about 400 meters up the road”?","qvi":"Tại sao người đàn ông nói: “Trung tâm du khách cách đây khoảng 400 mét”?","opts":["To correct some information","To offer a possible solution","To suggest a payment option","To point out a place to park"],"vi":["Để đính chính thông tin","Để đưa ra giải pháp","Để gợi ý cách thanh toán","Để chỉ chỗ đậu xe"],"ans":"B"}],"a":"E26-T07-53-55.mp3"},{"ns":[56,58],"script":[["M1","Good morning, Mayor Ishikawa. I'm glad you could join Ms. Schneider and me for the ceremony as we begin this important first step—the building demolition.","Chào buổi sáng, Thị trưởng Ishikawa. Tôi vui vì ông có thể tham gia cùng bà Schneider và tôi trong buổi lễ khi chúng ta bắt đầu bước quan trọng đầu tiên—phá dỡ tòa nhà."],["M2","Happy to be here. The city appreciates your company's involvement in this project.","Rất vui khi có mặt ở đây. Thành phố đánh giá cao sự tham gia của công ty ông vào dự án này."],["W","Our pleasure. TJO Property is excited to be investing in this community in such a substantial way.","Rất hân hạnh. TJO Property hào hứng đầu tư vào cộng đồng này một cách đáng kể."],["M1","Right. And tearing down this old shopping center will give us the space to create a new mixed-use project of apartments, shops, and offices.","Đúng vậy. Và phá dỡ trung tâm mua sắm cũ này sẽ cho chúng ta không gian để tạo dự án sử dụng hỗn hợp gồm căn hộ, cửa hàng và văn phòng."],["M2","Community residents are looking forward to the new development.","Cư dân cộng đồng đang mong chờ sự phát triển mới."],["W","Absolutely. Since the press is here, should we pose for a photograph in front of the wrecking ball before the work begins?","Chắc chắn rồi. Vì báo chí ở đây, chúng ta có nên tạo dáng chụp ảnh trước quả bóng phá dỡ trước khi công việc bắt đầu không?"]],"qs":[{"n":56,"q":"What are the speakers attending?","qvi":"Hai người đang tham dự sự kiện gì?","opts":["A property inspection","A contract signing","A building demolition","A grand opening"],"vi":["Kiểm tra tài sản","Ký hợp đồng","Phá dỡ tòa nhà","Lễ khai trương"],"ans":"C"},{"n":57,"q":"What does the woman say she is pleased about?","qvi":"Người phụ nữ nói cô ấy vui vì điều gì?","opts":["Using the latest technology","Improving safety policies","Keeping expenses within budget","Investing in a community"],"vi":["Sử dụng công nghệ mới nhất","Cải thiện chính sách an toàn","Giữ chi phí trong ngân sách","Đầu tư vào cộng đồng"],"ans":"D"},{"n":58,"q":"What does the woman suggest doing?","qvi":"Người phụ nữ gợi ý làm gì?","opts":["Distributing some handouts","Posing for a photograph","Enlarging some drawings","Scheduling an interview with a reporter"],"vi":["Phát tài liệu","Chụp ảnh","Phóng to bản vẽ","Sắp xếp buổi phỏng vấn với phóng viên"],"ans":"B"}],"a":"E26-T07-56-58.mp3"},{"ns":[59,61],"script":[["M","Welcome to Schmidt's. Are you interested in our hanging plants? I'm happy to help you choose.","Chào mừng đến với Schmidt's. Chị có quan tâm đến cây treo của chúng tôi không? Tôi rất sẵn lòng giúp chị chọn."],["W","Please! I got this coupon in the mail for fifteen percent off any outdoor plants. So, I thought I'd see if you have some flower baskets I could hang in my back patio area.","Vâng! Tôi nhận được phiếu giảm giá 15% cho bất kỳ cây ngoài trời nào qua thư. Nên tôi muốn xem anh có giỏ hoa nào tôi có thể treo ở khu vực hiên sau nhà không."],["M","These plants here bloom beautifully and do best in direct sunlight.","Những cây ở đây nở hoa đẹp và phát triển tốt nhất dưới ánh nắng trực tiếp."],["W","Well, it's a covered patio.","Ừm, đó là hiên có mái che."],["M","OK. Just follow me. We have plenty of plants that do well in shade or partial sun.","OK. Chị cứ đi theo tôi. Chúng tôi có nhiều loại cây phát triển tốt trong bóng râm hoặc nơi có nắng một phần."]],"qs":[{"n":59,"q":"Where does the man most likely work?","qvi":"Người đàn ông có khả năng làm việc ở đâu?","opts":["At a garden center","At a restaurant","At a furniture store","At a hardware store"],"vi":["Trung tâm cây cảnh","Nhà hàng","Cửa hàng nội thất","Cửa hàng dụng cụ"],"ans":"A"},{"n":60,"q":"What motivated the woman to visit the business?","qvi":"Điều gì khiến người phụ nữ đến cửa hàng?","opts":["She read about it in the newspaper.","She heard an announcement on the radio.","She received a coupon in the mail.","She saw an advertisement on TV."],"vi":["Cô đọc báo","Cô nghe thông báo trên radio","Cô nhận được phiếu giảm giá qua thư","Cô thấy quảng cáo trên TV"],"ans":"C"},{"n":61,"q":"Why does the woman say, “it’s a covered patio”?","qvi":"Tại sao người phụ nữ nói “nó là một hiên có mái che”?","opts":["To offer reassurance","To make a complaint","To explain a decision","To correct a misunderstanding"],"vi":["Để trấn an","Để phàn nàn","Để giải thích quyết định","Để sửa hiểu lầm"],"ans":"D"}],"a":"E26-T07-59-61.mp3"},{"ns":[62,64],"script":[["W","Hey, Pablo. I missed the intern team morning update. Was there information about cleaning acrylic test tubes? I wonder whether there are specific guidelines for these as opposed to glass tubes.","Này Pablo. Tôi bỏ lỡ cập nhật sáng đội thực tập. Có thông tin về làm sạch ống nghiệm acrylic không? Tôi tự hỏi có hướng dẫn cụ thể cho những cái này so với ống thủy tinh không."],["M","You should check the intern lab manual—I think it was updated this week with step-by-step instructions.","Cô nên kiểm tra sổ tay lab thực tập—Tôi nghĩ nó được cập nhật tuần này với hướng dẫn từng bước."],["W","Good idea! You know, what I'm enjoying most so far is learning about the practical side of the work. But I wish we could start working alongside the researchers here.","Ý hay! Anh biết không, điều tôi thích nhất đến nay là học về khía cạnh thực tế của công việc. Nhưng tôi ước chúng ta có thể bắt đầu làm việc cùng các nhà nghiên cứu ở đây."],["M","Professor Kwon is showing us how to analyze data later today. She usually asks the interns to participate.","Giáo sư Kwon sẽ chỉ chúng ta cách phân tích dữ liệu sau hôm nay. Bà ấy thường yêu cầu thực tập sinh tham gia."]],"qs":[{"n":62,"q":"Who are the speakers?","qvi":"Hai người là ai?","opts":["Interns","Researchers","Maintenance staff","Inspectors"],"vi":["Thực tập sinh","Nhà nghiên cứu","Nhân viên bảo trì","Thanh tra"],"ans":"A"},{"n":63,"q":"Why should the woman check a manual?","qvi":"Tại sao người phụ nữ nên xem sổ tay hướng dẫn?","opts":["To review waste disposal instructions","To learn how to clean some equipment","To check which chemicals to use","To determine which protective clothing to wear"],"vi":["Xem hướng dẫn xử lý rác","Học cách vệ sinh thiết bị","Kiểm tra hóa chất cần dùng","Xác định loại đồ bảo hộ cần mặc"],"ans":"B"},{"n":64,"q":"Look at the graphic. What day does the conversation take place?","qvi":"Nhìn vào hình. Cuộc trò chuyện diễn ra vào ngày nào?","opts":["On Monday","On Tuesday","On Wednesday","On Thursday"],"vi":["Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm"],"ans":"D"}],"a":"E26-T07-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Hi, Farida. I'm excited to see the designs you created. People spend a lot of time outside during the summer, so we want to get our sunscreen on store shelves before the summer rush. We need to pick a logo design quickly.","Chào Farida. Tôi hào hứng xem các thiết kế cô tạo. Mọi người dành nhiều thời gian ngoài trời mùa hè, nên chúng ta muốn đưa kem chống nắng lên kệ trước cao điểm hè. Chúng ta cần chọn thiết kế logo nhanh."],["W","Take a look at these logo designs. All of them will grab the attention of shoppers.","Xem các thiết kế logo này. Tất cả sẽ thu hút sự chú ý của người mua sắm."],["M","I like this one with the palm tree in a circle.","Tôi thích cái có cây cọ trong vòng tròn."],["W","I agree. The single palm tree's a simple, clean logo.","Tôi đồng ý. Cây cọ đơn giản là logo sạch sẽ."],["M","Before we make our decision, I'd like to show it to a focus group that represents our target audience. We have a large group coming in next week.","Trước khi quyết định, tôi muốn cho nhóm tập trung đại diện khán giả mục tiêu xem. Chúng ta có nhóm lớn đến tuần tới."]],"qs":[{"n":65,"q":"Why does the man want to make a decision quickly?","qvi":"Tại sao người đàn ông muốn quyết định nhanh?","opts":["A busy season is approaching.","A team is starting another project.","A client has changed a deadline.","A permit must be renewed."],"vi":["Mùa bận rộn sắp đến.","Nhóm đang bắt đầu dự án khác.","Khách hàng thay đổi thời hạn.","Giấy phép cần được gia hạn."],"ans":"A"},{"n":66,"q":"Look at the graphic. Which logo design does the man prefer?","qvi":"Nhìn vào hình. Người đàn ông thích mẫu logo nào?","opts":["Design 1","Design 2","Design 3","Design 4"],"vi":["Mẫu 1","Mẫu 2","Mẫu 3","Mẫu 4"],"ans":"D"},{"n":67,"q":"What is scheduled for next week?","qvi":"Tuần sau có lịch gì?","opts":["A trade show","A focus group","A store opening","A safety inspection"],"vi":["Hội chợ thương mại","Nhóm thảo luận","Khai trương cửa hàng","Kiểm tra an toàn"],"ans":"B"}],"a":"E26-T07-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","Stefan, have you given any more thought to that parcel of land that's available for lease? If we leased it, we'd have space for a lot more crops this spring and summer.","Stefan, anh đã nghĩ thêm về mảnh đất có sẵn cho thuê chưa? Nếu thuê, chúng ta sẽ có không gian cho nhiều cây trồng hơn mùa xuân và hè này."],["M","Yes, with the extra growing space, we'd definitely increase our yield. What crops do you think would be best?","Có, với không gian trồng thêm, chúng ta chắc chắn tăng năng suất. Anh nghĩ cây trồng nào tốt nhất?"],["W","Well, we could plant more celery, which is our most popular crop. And we could even add cabbage as a new crop in the spring.","Ừm, chúng ta có thể trồng thêm cần tây, là cây trồng phổ biến nhất. Và thậm chí thêm bắp cải làm cây mới mùa xuân."],["M","That makes sense. We'll need to extend our irrigation system to the new parcel, though, and that could be expensive. I can call Lynden Ag Supply for an estimate on that.","Hợp lý. Nhưng chúng ta cần mở rộng hệ thống tưới đến mảnh mới, và có thể đắt. Tôi có thể gọi Lynden Ag Supply để lấy ước tính."],["W","Sure, that would be great.","Chắc chắn, tốt lắm."]],"qs":[{"n":68,"q":"What does the woman ask about?","qvi":"Người phụ nữ hỏi về điều gì?","opts":["Leasing some land","Offering workshops","Opening a farm stand","Replacing some equipment"],"vi":["Thuê đất","Tổ chức hội thảo","Mở quầy bán nông sản","Thay thế thiết bị"],"ans":"A"},{"n":69,"q":"Look at the graphic. When is the most popular crop planted?","qvi":"Nhìn vào hình. Loại cây trồng phổ biến nhất được trồng khi nào?","opts":["Spring","Early summer","Late summer","Fall"],"vi":["Mùa xuân","Đầu mùa hè","Cuối mùa hè","Mùa thu"],"ans":"B"},{"n":70,"q":"What does the man offer to do?","qvi":"Người đàn ông đề nghị làm gì?","opts":["Check an inventory","Select some seeds","Get an estimate","Reach out to customers"],"vi":["Kiểm tra kho hàng","Chọn hạt giống","Lấy báo giá","Liên hệ khách hàng"],"ans":"C"}],"a":"E26-T07-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Good morning, everyone. Thank you for coming in a little bit early for your shift today. While production was closed down for the holiday, management took the opportunity to install a new type of safety equipment on all the machines on the assembly lines. A special sensor called a light curtain automatically turns off the machines if an object gets too close during operation. I'd like to show you how it works. Let's go look at a machine now.","Chào buổi sáng, mọi người. Cảm ơn vì đã đến sớm một chút cho ca làm việc hôm nay. Trong khi sản xuất bị đóng cửa vì kỳ nghỉ, ban quản lý đã tận dụng cơ hội để lắp đặt loại thiết bị an toàn mới trên tất cả các máy móc trên dây chuyền lắp ráp. Một cảm biến đặc biệt gọi là rèm ánh sáng tự động tắt máy nếu một vật thể đến quá gần trong quá trình hoạt động. Tôi muốn cho các bạn thấy cách nó hoạt động. Bây giờ chúng ta đi xem một máy nhé."]],"qs":[{"n":71,"q":"Why does the speaker thank the listeners?","qvi":"Tại sao người nói cảm ơn người nghe?","opts":["For responding to an employee survey","For arriving early for a shift","For agreeing to work overtime","For planning a holiday party"],"vi":["Trả lời khảo sát nhân viên","Đến sớm để làm việc","Đồng ý tăng ca","Lên kế hoạch cho bữa tiệc"],"ans":"B"},{"n":72,"q":"Where do the listeners most likely work?","qvi":"Người nghe có khả năng làm việc ở đâu?","opts":["At an appliance store","At a hotel","At a factory","At a hospital"],"vi":["Cửa hàng thiết bị gia dụng","Khách sạn","Nhà máy","Bệnh viện"],"ans":"C"},{"n":73,"q":"What will the speaker do next?","qvi":"Người nói sẽ làm gì tiếp theo?","opts":["Give a demonstration","Distribute some documents","Authorize a purchase","Conduct some interviews"],"vi":["Thực hiện trình diễn","Phát tài liệu","Phê duyệt mua hàng","Tiến hành phỏng vấn"],"ans":"A"}],"a":"E26-T07-71-73.mp3"},{"ns":[74,76],"script":[["","Good job at all the rehearsals this week as we prepare for our upcoming performance, dancers. You did great at quickly learning the newly choreographed steps to our main piece. I recommend that you rest a lot over the weekend. Please give your muscles time to recover after working so hard. When we return on Monday for our final rehearsal, Erina will be here. She's in charge of the costumes and will be making last-minute alterations to your outfits. Then we'll be ready for our first show on Tuesday night!","Làm tốt lắm ở tất cả các buổi tập dượt tuần này khi chúng ta chuẩn bị cho buổi biểu diễn sắp tới, các vũ công. Các bạn đã làm tuyệt vời khi nhanh chóng học các bước nhảy mới được biên đạo cho phần chính của chúng ta. Tôi khuyên các bạn nên nghỉ ngơi nhiều vào cuối tuần. Hãy cho cơ bắp của bạn thời gian để phục hồi sau khi làm việc chăm chỉ như vậy. Khi chúng ta trở lại vào thứ Hai cho buổi tập dượt cuối cùng, Erina sẽ ở đây. Cô ấy phụ trách trang phục và sẽ thực hiện các sửa đổi cuối cùng cho trang phục của các bạn. Sau đó chúng ta sẽ sẵn sàng cho buổi biểu diễn đầu tiên vào tối thứ Ba!"]],"qs":[{"n":74,"q":"What does the speaker compliment the listeners on?","qvi":"Người nói khen người nghe về điều gì?","opts":["Decorating an auditorium","Learning new dance steps","Selling tickets for a performance","Winning a competition"],"vi":["Trang trí khán phòng","Học bước nhảy mới","Bán vé cho buổi diễn","Thắng cuộc thi"],"ans":"B"},{"n":75,"q":"What does the speaker recommend doing?","qvi":"Người nói khuyên nên làm gì?","opts":["Getting some rest","Drinking lots of water","Opening a window","Scheduling an additional performance"],"vi":["Nghỉ ngơi","Uống nhiều nước","Mở cửa sổ","Xếp thêm buổi biểu diễn"],"ans":"A"},{"n":76,"q":"What is Erina responsible for?","qvi":"Erina phụ trách việc gì?","opts":["Payroll","Marketing","Lighting","Costumes"],"vi":["Trả lương","Marketing","Ánh sáng sân khấu","Phục trang"],"ans":"D"}],"a":"E26-T07-74-76.mp3"},{"ns":[77,79],"script":[["","Attention, everyone. Tonight we're filming a live performance of the Edmunsen Symphony Orchestra, so the margin for error is zero. I know we've had a lot of adjustments to make since we just upgraded our cameras to newer models last week, but we've tested everything, and we know what we're doing. Remember, it's an important night because this is a high-profile event that will be broadcast live to viewers. If we do a great job, our services are bound to be in demand. It's noon now, so let's break for lunch. When we come back, we'll get set up.","Chú ý, mọi người. Tối nay chúng ta đang quay buổi biểu diễn trực tiếp của Dàn nhạc Giao hưởng Edmunsen, vì vậy chúng ta không được để xảy ra sai sót. Tôi biết chúng ta đã phải điều chỉnh nhiều kể từ khi chúng ta vừa nâng cấp máy quay lên các mẫu mới hơn tuần trước, nhưng chúng ta đã kiểm tra mọi thứ, và chúng ta biết mình đang làm gì. Hãy nhớ rằng, đó là một đêm quan trọng vì đây là sự kiện nổi bật sẽ được phát sóng trực tiếp đến khán giả. Nếu chúng ta làm tốt, dịch vụ của chúng ta chắc chắn sẽ được đặt hàng nhiều. Bây giờ là trưa, vậy hãy nghỉ ăn trưa. Khi chúng ta quay lại, chúng ta sẽ bắt đầu."]],"qs":[{"n":77,"q":"Who most likely are the listeners?","qvi":"Người nghe có thể là ai?","opts":["Musicians","Actors","A television production team","Software technicians"],"vi":["Nhạc công","Diễn viên","Đội sản xuất truyền hình","Kỹ thuật viên phần mềm"],"ans":"C"},{"n":78,"q":"What does the speaker say happened last week?","qvi":"Người nói nói điều gì đã xảy ra tuần trước?","opts":["An article was published.","A renovation was completed.","A budget was approved.","Some equipment was replaced."],"vi":["Có bài báo được đăng","Hoàn thành cải tạo","Phê duyệt ngân sách","Thay thiết bị"],"ans":"D"},{"n":79,"q":"What will the listeners do next?","qvi":"Người nghe sẽ làm gì tiếp theo?","opts":["Pose for photographs","Tune some instruments","Interview a celebrity","Take a break"],"vi":["Chụp ảnh","Chỉnh nhạc cụ","Phỏng vấn người nổi tiếng","Nghỉ giải lao"],"ans":"D"}],"a":"E26-T07-77-79.mp3"},{"ns":[80,82],"script":[["","Hi. I'm your supervisor, Maria Gonzales. I'd like to extend a warm welcome to everyone here. I'm excited that you'll all be joining the customer service department. I hope that the onboarding process has been going well so far. After lunch, I'll share a video about our company's history, from its founding in 1971 to the present day. Let's move on now to introductions. I'd like all of you to tell us something about yourselves. For example, I just found out that Astrid plays saxophone in a jazz ensemble. That certainly wasn't on her résumé. Klaus, would you go first?","Chào. Tôi là giám sát viên của bạn, Maria Gonzales. Tôi muốn gửi lời chào mừng nồng nhiệt đến mọi người ở đây. Tôi rất hào hứng rằng tất cả các bạn sẽ tham gia bộ phận dịch vụ khách hàng. Tôi hy vọng quá trình onboarding đã diễn ra tốt đẹp cho đến nay. Sau bữa trưa, tôi sẽ chia sẻ một video về lịch sử công ty của chúng ta, từ khi thành lập năm 1971 đến nay. Bây giờ hãy chuyển sang phần giới thiệu. Tôi muốn tất cả các bạn kể cho chúng tôi điều gì đó về bản thân. Ví dụ, Tôi vừa biết rằng Astrid chơi saxophone trong một nhóm jazz. Điều đó chắc chắn không có trên sơ yếu lý lịch của cô ấy. Klaus, bạn nói trước nhé?"]],"qs":[{"n":80,"q":"What is the purpose of the talk?","qvi":"Mục đích của buổi nói chuyện là gì?","opts":["To welcome new employees","To explain a new policy","To celebrate a team’s achievements","To share customer feedback"],"vi":["Chào đón nhân viên mới","Giải thích chính sách mới","Chúc mừng thành tích nhóm","Chia sẻ phản hồi khách hàng"],"ans":"A"},{"n":81,"q":"What will the listeners do after lunch?","qvi":"Người nghe sẽ làm gì sau bữa trưa?","opts":["Sign a document","Watch a video","Meet with some customers","Plan an event"],"vi":["Ký tài liệu","Xem video","Gặp khách hàng","Lên kế hoạch sự kiện"],"ans":"B"},{"n":82,"q":"Why does the speaker say, “That certainly wasn’t on her résumé”?","qvi":"Tại sao người nói nói “Điều đó chắc chắn không có trong hồ sơ xin việc”?","opts":["To express surprise","To offer a recommendation","To make an excuse","To show disappointment"],"vi":["Thể hiện ngạc nhiên","Đưa ra lời khuyên","Bao biện","Thể hiện thất vọng"],"ans":"A"}],"a":"E26-T07-80-82.mp3"},{"ns":[83,85],"script":[["","Good afternoon and welcome aboard this train to Ashedale. Our next stop is Bruxton, famous for being the birthplace of renowned painter Oliver Murray. As you may know, several of Mr. Murray's paintings hang in museums around the world. Please be advised that due to the short platform length, the doors of the last train car will not open. If you are in that car, you'll need to walk forward to exit the train. There will also be a short delay at this station while our new train crew comes on and gets situated. We apologize for any inconvenience.","Chào buổi chiều và chào mừng lên tàu chuyến tàu này đến Ashedale. Trạm dừng tiếp theo của chúng ta là Bruxton, nổi tiếng là nơi sinh của họa sĩ nổi tiếng Oliver Murray. Như bạn có thể biết, một số bức tranh của ông Murray treo ở các bảo tàng trên thế giới. Xin lưu ý rằng do chiều dài sân ga ngắn, cửa của toa tàu cuối cùng sẽ không mở. Nếu bạn ở toa đó, bạn cần đi về phía trước để ra khỏi tàu. Cũng sẽ có một chút chậm trễ tại ga này trong khi phi hành đoàn tàu mới lên và ổn định. Chúng tôi xin lỗi vì bất kỳ sự bất tiện nào."]],"qs":[{"n":83,"q":"What does the speaker say Bruxton is known for?","qvi":"Theo người nói, Bruxton nổi tiếng vì điều gì?","opts":["Its architectural landmarks","Its archaeological significance","Its connections to a renowned artist","Its collection of botanical gardens"],"vi":["Các công trình kiến trúc","Giá trị khảo cổ","Mối liên hệ với một nghệ sĩ nổi tiếng","Vườn thực vật"],"ans":"C"},{"n":84,"q":"According to the speaker, what should some passengers in the last car do?","qvi":"Theo người nói, một số hành khách ở toa cuối nên làm gì?","opts":["Present their tickets to the conductor","Move to a car ahead of theirs","Store heavy luggage in another car","Refrain from talking on mobile phones"],"vi":["Xuất trình vé cho nhân viên","Di chuyển sang toa trước","Bỏ hành lý nặng sang toa khác","Hạn chế nói chuyện điện thoại"],"ans":"B"},{"n":85,"q":"According to the speaker, why will there be a delay?","qvi":"Vì sao sẽ có sự chậm trễ?","opts":["A staff change will take place.","An express train needs to pass.","Maintenance work is being done.","Weather conditions require caution."],"vi":["Có thay đổi nhân sự","Tàu tốc hành cần đi qua","Đang bảo trì","Thời tiết cần được chú ý"],"ans":"A"}],"a":"E26-T07-83-85.mp3"},{"ns":[86,88],"script":[["","I have good news! We've signed a contract with Lammert Technologies to plan the gardens and landscaping around their new office building. I met with them last week to present our design proposals, and they agreed on a design plan. They've decided to cover a lot of the open space with creeping thyme plantings instead of grass. Resource conservation is a priority for all of us. And I must say, grass does require a lot of water. The project will start in August. I'll need to make the work schedule soon. If you're planning to take any time off for vacation, send me those dates today, please.","Tôi có tin tốt! Chúng tôi đã ký hợp đồng với Lammert Technologies để lập kế hoạch vườn và cảnh quan xung quanh tòa nhà văn phòng mới của họ. Tôi đã gặp họ tuần trước để trình bày các đề xuất thiết kế của chúng tôi, và họ đồng ý với kế hoạch thiết kế. Họ đã quyết định bao phủ phần lớn không gian mở bằng cây thyme leo thay vì cỏ. Bảo tồn tài nguyên là ưu tiên cho tất cả chúng ta. Và tôi phải nói, cỏ đòi hỏi rất nhiều nước. Dự án sẽ bắt đầu vào tháng Tám. Tôi cần lập lịch làm việc sớm. Nếu bạn đang lập kế hoạch nghỉ phép, hãy gửi cho tôi những ngày đó hôm nay."]],"qs":[{"n":86,"q":"What industry does the speaker most likely work in?","qvi":"Người nói có khả năng làm việc trong ngành nào?","opts":["Landscape design","Architecture","Agriculture","Corporate catering"],"vi":["Thiết kế cảnh quan","Kiến trúc","Nông nghiệp","Dịch vụ ăn uống doanh nghiệp"],"ans":"A"},{"n":87,"q":"What does the speaker mean when she says, “grass does require a lot of water”?","qvi":"Ý người nói khi nói “cỏ cần nhiều nước” là gì?","opts":["She agrees with a choice.","She needs volunteers to help.","Water costs have increased.","A design plan should be changed."],"vi":["Đồng ý với lựa chọn","Cần người hỗ trợ","Chi phí nước tăng","Cần thay đổi bản thiết kế"],"ans":"A"},{"n":88,"q":"What does the speaker ask the listeners to send her?","qvi":"Người nói yêu cầu người nghe gửi gì?","opts":["Supply lists","Photographs","Vacation dates","Travel recommendations"],"vi":["Danh sách vật tư","Ảnh chụp","Lịch nghỉ mát","Gợi ý du lịch"],"ans":"C"}],"a":"E26-T07-86-88.mp3"},{"ns":[89,91],"script":[["","A market research firm has reported that the department store chain Willoughby is partnering with the beauty retailer Rossi. By the end of the year, Rossi stores will be in place at 500 Willoughby locations. Currently, most of the beauty retailer's sales come from small shops in urban areas. By joining forces with Willoughby, Rossi hopes to meet its goal of expanding its customer base by entering suburban markets. To accommodate the new retail spaces for Rossi, participating Willoughby stores will start renovations in July.","Một công ty nghiên cứu thị trường đã báo cáo rằng chuỗi cửa hàng bách hóa Willoughby đang hợp tác với nhà bán lẻ mỹ phẩm Rossi. Vào cuối năm, các cửa hàng Rossi sẽ được đặt tại 500 địa điểm Willoughby. Hiện tại, hầu hết doanh số của nhà bán lẻ mỹ phẩm này đến từ các cửa hàng nhỏ ở khu vực đô thị. Bằng cách hợp lực với Willoughby, Rossi hy vọng đạt được mục tiêu mở rộng cơ sở khách hàng bằng cách thâm nhập thị trường ngoại ô. Để phù hợp với không gian bán lẻ mới cho Rossi, các cửa hàng Willoughby tham gia sẽ bắt đầu cải tạo vào tháng Bảy."]],"qs":[{"n":89,"q":"What is the broadcast mainly about?","qvi":"Chương trình phát thanh chủ yếu nói về điều gì?","opts":["A new company owner","A business partnership","Some store closings","A product rebranding"],"vi":["Chủ doanh nghiệp mới","Quan hệ hợp tác doanh nghiệp","Một số cửa hàng sắp đóng cửa","Đổi thương hiệu sản phẩm"],"ans":"B"},{"n":90,"q":"What goal does the speaker mention?","qvi":"Người nói đề cập mục tiêu gì?","opts":["Introducing a new product line","Becoming more environmentally friendly","Launching a social media campaign","Expanding a customer base"],"vi":["Giới thiệu sản phẩm mới","Thân thiện hơn với môi trường","Ra mắt chiến dịch mạng xã hội","Mở rộng tập khách hàng"],"ans":"D"},{"n":91,"q":"What does the Willoughby store chain plan to do in July?","qvi":"Cửa hàng Willoughby lên kế hoạch gì vào tháng 7?","opts":["Renovate some of its stores","Display beachwear","Host a grand opening event","Distribute a customer survey"],"vi":["Cải tạo một số cửa hàng","Trưng bày đồ bơi","Tổ chức lễ khai trương","Phát khảo sát khách hàng"],"ans":"A"}],"a":"E26-T07-89-91.mp3"},{"ns":[92,94],"script":[["","Today I want to discuss some ways we can improve our solar panel installation business. I'd like to pay for national certification for all of our installation techs, which will greatly improve our quality. Let's not forget that the Business Council's yearly ratings will be published soon. In addition, we can attract new customers by offering 25 percent off the installation charge. I suggest we begin the promotion next month.","Hôm nay tôi muốn thảo luận một số cách để cải thiện kinh doanh lắp đặt pin mặt trời của chúng ta. Tôi muốn trả tiền cho chứng chỉ quốc gia cho tất cả các kỹ thuật viên lắp đặt của chúng ta, điều này sẽ cải thiện chất lượng của chúng ta rất nhiều. Đừng quên rằng đánh giá hàng năm của Hội đồng Kinh doanh sẽ được công bố sớm. Ngoài ra, chúng ta có thể thu hút khách hàng mới bằng cách giảm 25 phần trăm phí lắp đặt. Tôi đề nghị chúng ta bắt đầu chương trình khuyến mãi vào tháng tới."]],"qs":[{"n":92,"q":"What is the purpose of the meeting?","qvi":"Mục đích của cuộc họp là gì?","opts":["To propose increasing an advertising budget","To announce a company merger","To discuss ways to improve a business","To recommend developing new products"],"vi":["Đề xuất tăng ngân sách quảng cáo","Thông báo sáp nhập công ty","Thảo luận cách cải thiện kinh doanh","Gợi ý phát triển sản phẩm mới"],"ans":"C"},{"n":93,"q":"Why does the speaker say, “Let’s not forget that the Business Council’s yearly ratings will be published soon”?","qvi":"Tại sao người nói nói: “Đừng quên rằng bảng xếp hạng hàng năm của Hội đồng Kinh doanh sắp được công bố”?","opts":["To offer to form a committee","To support a proposal","To congratulate award winners","To suggest joining an organization"],"vi":["Đề nghị lập ủy ban","Ủng hộ đề xuất","Chúc mừng người thắng giải","Khuyến khích tham gia tổ chức"],"ans":"B"},{"n":94,"q":"What does the speaker suggest doing next month?","qvi":"Người nói dự định làm gì vào tháng tới?","opts":["Advertising on social media","Hiring additional employees","Finalizing a production schedule","Offering a discount to new customers"],"vi":["Quảng cáo trên mạng xã hội","Tuyển thêm nhân viên","Hoàn tất lịch trình sản xuất","Giảm giá cho khách mới"],"ans":"D"}],"a":"E26-T07-92-94.mp3"},{"ns":[95,97],"script":[["","Thank you for attending. Last fall, the city approved more funding for transportation projects. Today my department is happy to announce that we'll use some of those funds to install covered benches at city bus stops. They will give riders a place to rest and keep out of the sun, rain, or snow while they wait. This map shows the neighborhoods where we'll construct new bus shelters. We'll start with the neighborhood around the university since students make up a large portion of the overall ridership.","Cảm ơn bạn đã tham dự. Mùa thu năm ngoái, thành phố đã phê duyệt thêm kinh phí cho các dự án giao thông. Hôm nay bộ phận của tôi rất vui mừng thông báo rằng chúng tôi sẽ sử dụng một phần kinh phí đó để lắp đặt ghế có mái che tại các điểm dừng xe buýt thành phố. Chúng sẽ cung cấp cho hành khách một nơi nghỉ ngơi và tránh nắng, mưa hoặc tuyết trong khi chờ đợi. Bản đồ này cho thấy các khu vực nơi chúng tôi sẽ xây dựng các chỗ trú xe buýt mới. Chúng tôi sẽ bắt đầu với khu vực xung quanh đại học vì sinh viên chiếm một phần lớn tổng số hành khách."]],"qs":[{"n":95,"q":"What happened last fall?","qvi":"Chuyện gì xảy ra mùa thu năm ngoái?","opts":["An electric train line was added.","A construction project was interrupted.","Some computer systems were upgraded.","Some city funding was approved."],"vi":["Thêm tuyến tàu điện","Dự án xây dựng bị gián đoạn","Nâng cấp hệ thống máy tính","Thành phố phê duyệt ngân sách"],"ans":"D"},{"n":96,"q":"What department does the speaker most likely work in?","qvi":"Người nói có khả năng làm việc ở phòng ban nào?","opts":["Permits","Transportation","Parks","Housing"],"vi":["Cấp phép xây dựng","Giao thông vận tải","Công viên","Nhà ở"],"ans":"B"},{"n":97,"q":"Look at the graphic. Which neighborhood will be served first?","qvi":"Nhìn vào hình. Khu vực nào sẽ được phục vụ trước?","opts":["Bradley Heights","Rosewood","Centerville","Lakeview"],"vi":["Bradley Heights","Rosewood","Centerville","Lakeview"],"ans":"B"}],"a":"E26-T07-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Hi, Andrew. This is Samantha Evans. It was great running into you at the flower trade show in Boston. And thanks for recommending that I visit the art museum while I was in town. I really enjoyed seeing the modern art exhibit. I'm calling because I wanted to follow up with you right away about the tulips you're getting shipped from the Netherlands next week. I'd like to buy ten dozen tulips from you for my flower shop. However, my budget is tight and I can't spend more than $250.00, so I'd like to order tulips in that price range.","Chào Andrew. Đây là Samantha Evans. Thật tuyệt khi tình cờ gặp anh tại triển lãm hoa ở Boston. Và cảm ơn vì đã khuyến nghị tôi thăm bảo tàng nghệ thuật khi ở thành phố. Tôi thực sự thích xem triển lãm nghệ thuật hiện đại. Tôi gọi vì muốn báo ngay với anh về những bông tulip anh sẽ nhận hàng từ Hà Lan tuần tới. Tôi muốn mua mười tá tulip từ anh cho cửa hàng hoa của tôi. Tuy nhiên, ngân sách của tôi khá eo hẹp và tôi không thể chi hơn 250 đô la, vì vậy tôi muốn đặt hàng tulip trong phạm vi giá đó."]],"qs":[{"n":98,"q":"What does the speaker say she enjoyed seeing while she was in Boston?","qvi":"Người nói nói rằng cô ấy thích xem gì khi ở Boston?","opts":["An art exhibit","A sports event","A holiday parade","A rock concert"],"vi":["Triển lãm nghệ thuật","Sự kiện thể thao","Lễ diễu hành","Buổi hòa nhạc rock"],"ans":"A"},{"n":99,"q":"Who most likely is the speaker?","qvi":"Người nói có khả năng là ai?","opts":["An interior decorator","A shop owner","A journalist","A painter"],"vi":["Nhà thiết kế nội thất","Chủ cửa hàng","Nhà báo","Họa sĩ"],"ans":"B"},{"n":100,"q":"Look at the graphic. What type of tulips will the speaker most likely order?","qvi":"Nhìn vào hình. Người nói nhiều khả năng sẽ đặt loại hoa tulip nào?","opts":["Fringed tulips","Triumph tulips","Double early tulips","Parrot tulips"],"vi":["Tulip viền tua rua","Tulip Triumph","Tulip nở sớm","Tulip vẹt"],"ans":"C"}],"a":"E26-T07-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"After Ms. Takido finishes ------- presentation, the audience will be permitted to ask questions.","opts":["her","she","hers","herself"],"ans":"A","xp":"Chọn (A) her\nGiải thích: Vị trí trống đứng trước danh từ \"presentation\" (bài thuyết trình). Chúng ta cần một tính từ sở hữu (Possessive Adjective) để bổ nghĩa cho danh từ này.\n(B) she: Đại từ nhân xưng đóng vai trò chủ ngữ.\n(C) hers: Đại từ sở hữu (bằng her + danh từ), không đứng trước danh từ.\n(D) herself: Đại từ phản thân.\nDịch: Sau khi bà Takido kết thúc bài thuyết trình của mình, khán giả sẽ được phép đặt câu hỏi."},{"n":102,"q":"Mike’s Café offers a free ------- with every meal on Tuesdays from 11 A.M. to 7 P.M.","opts":["table","drink","price","menu"],"ans":"B","xp":"Chọn (B) drink\nGiải thích: Xét về mặt ý nghĩa (ngữ cảnh), một quán cà phê (Café) thường tặng kèm đồ uống (drink) miễn phí khi khách dùng bữa.\n(A) table (bàn)\n(C) price (giá cả)\n(D) menu (thực đơn)\nDịch: Quán Café của Mike tặng một đồ uống miễn phí kèm theo mỗi bữa ăn vào các ngày Thứ Ba, từ 11 giờ sáng đến 7 giờ tối."},{"n":103,"q":"Mr. Ozawa generally prefers ------- to work by train instead of by car.","opts":["commute","to commute","having commuted","is commuting"],"ans":"B","xp":"Chọn (B) to commute\nGiải thích: Cấu trúc động từ: Prefer + to-V hoặc Prefer + V-ing (thích làm việc gì hơn). Trong các lựa chọn, chỉ có \"to commute\" là phù hợp cấu trúc ngữ pháp sau động từ \"prefers\".\nDịch: Ông Ozawa thường thích đi làm bằng tàu hỏa hơn là đi bằng ô tô."},{"n":104,"q":"------- the new branch office was understaffed, more workers were hired.","opts":["Because","Having","Usually","Following"],"ans":"A","xp":"Chọn (A) Because\nGiải thích: Sau khoảng trống là một mệnh đề hoàn chỉnh (S + V): \"the new branch office was understaffed\". Do đó, ta cần một liên từ (Conjunction) để chỉ nguyên nhân.\n(B) Having: Thường dùng trong cấu trúc rút gọn mệnh đề, không đứng trước một mệnh đề có chủ ngữ rõ ràng như trên.\n(C) Usually: Trạng từ chỉ tần suất, không dùng để nối hai mệnh đề.\n(D) Following: Giới từ (sau khi), thường đi kèm với một cụm danh từ.\nDịch: Vì chi nhánh văn phòng mới thiếu nhân sự, nhiều công nhân đã được thuê thêm."},{"n":105,"q":"Dumbbells, also known as free weights, are ------- for keeping fit at home.","opts":["use","using","to use","useful"],"ans":"D","xp":"Chọn (D) useful\nGiải thích: Vị trí trống đứng sau động từ tobe \"are\". Chúng ta cần một tính từ (Adjective) để miêu tả đặc điểm của chủ ngữ \"Dumbbells\" (tạ tay).\nDịch: Tạ tay, còn được gọi là tạ tự do, rất hữu ích cho việc giữ gìn vóc dáng tại nhà."},{"n":106,"q":"The scheduled completion date was September 4, but the job was ------- finished two weeks ahead of schedule.","opts":["additionally","rarely","extremely","actually"],"ans":"D","xp":"Chọn (D) actually\nGiải thích: Trạng từ actually (thực sự/thực tế là) được dùng để nhấn mạnh một sự thật trái ngược hoặc bất ngờ so với dự tính ban đầu (ngày 4 tháng 9).\n(A) additionally: thêm vào đó.\n(B) rarely: hiếm khi.\n(C) extremely: cực kỳ (thường bổ nghĩa cho tính từ).\nDịch: Ngày hoàn thành dự kiến là ngày 4 tháng 9, nhưng công việc thực tế đã được hoàn thành trước thời hạn hai tuần."},{"n":107,"q":"Please click on the ------- below to subscribe to our monthly newsletter.","opts":["link","linker","linking","linkage"],"ans":"A","xp":"Chọn (A) link\nGiải thích: Vị trí này cần một danh từ sau mạo từ \"the\".\nDịch: Vui lòng nhấp vào đường dẫn bên dưới để đăng ký nhận bản tin hàng tháng của chúng tôi."},{"n":108,"q":"Candidates for the entry-level marketing position need to have a ------- understanding of consumer behavior.","opts":["proud","basic","short","considerate"],"ans":"B","xp":"Chọn (B) basic\nGiải thích: Cụm từ basic understanding (kiến thức cơ bản/sự hiểu biết cơ bản) là một kết hợp từ (collocation) phổ biến.\n(A) proud: tự hào.\n(C) short: ngắn.\n(D) considerate: chu đáo/thận trọng.\nDịch: Các ứng viên cho vị trí tiếp thị cấp độ mới bắt đầu cần có sự hiểu biết cơ bản về hành vi người tiêu dùng."},{"n":109,"q":"Ms. Persson was able to respond ------- to government leaders about their concerns regarding the funding plan.","opts":["directly","direct","directions","directed"],"ans":"A","xp":"Chọn (A) directly\nGiải thích: Vị trí này cần một trạng từ (Adverb) để bổ nghĩa cho động từ \"respond\".\nDịch: Bà Persson đã có thể phản hồi trực tiếp tới các nhà lãnh đạo chính phủ về những lo ngại của họ liên quan đến kế hoạch tài trợ."},{"n":110,"q":"Leigh Ainsley, the featured soloist in tonight’s performance, began taking violin lessons ------- the age of five.","opts":["on","at","with","along"],"ans":"B","xp":"Chọn (B) at\nGiải thích: Cấu trúc cố định chỉ độ tuổi: at the age of + số tuổi.\nDịch: Leigh Ainsley, nghệ sĩ độc tấu chính trong buổi biểu diễn tối nay, đã bắt đầu học violin từ năm 5 tuổi."},{"n":111,"q":"From among the seven candidates for the management position, the hiring committee must choose only -------.","opts":["one","either","such","other"],"ans":"A","xp":"Chọn (A) one\nGiải thích: Đại từ one đại diện cho một người trong số nhóm đã được nhắc đến (seven candidates).\n(B) either: một trong hai (ở đây có 7 người nên không dùng either).\n(C) such: như thế (không làm đại từ thay thế số lượng ở đây).\n(D) other: khác (thường cần \"the\" hoặc ở số nhiều \"others\" để làm đại từ).\nDịch: Trong số bảy ứng viên cho vị trí quản lý, ủy ban tuyển dụng chỉ được chọn một người."},{"n":112,"q":"GT International Foods sells unique products that are difficult to find -------.","opts":["aside","instead","likewise","elsewhere"],"ans":"D","xp":"Chọn (D) elsewhere\nGiải thích: Trạng từ elsewhere (ở nơi khác) hoàn thiện ý nghĩa của câu: những sản phẩm này khó tìm thấy ở bất kỳ nơi nào khác.\n(A) aside: sang một bên.\n(B) instead: thay vào đó.\n(C) likewise: tương tự như vậy.\nDịch: GT International Foods bán những sản phẩm độc đáo mà khó có thể tìm thấy ở những nơi khác."},{"n":113,"q":"Contact the hotel’s main office ------- you wish to receive daily linen service.","opts":["moreover","besides","if","also"],"ans":"C","xp":"Chọn (C) if\nGiải thích: Đây là một câu điều kiện: \"if\" (nếu) nối mệnh đề điều kiện \"you wish to receive daily linen service\".\n(A) moreover, (B) besides, (D) also: Đều là các trạng từ liên kết, không dùng để nối mệnh đề phụ thuộc trong ngữ cảnh này.\nDịch: Hãy liên hệ với văn phòng chính của khách sạn nếu bạn muốn nhận dịch vụ thay khăn trải giường hàng ngày."},{"n":114,"q":"Please ------- yourself with the company’s tuition-reimbursement policy before enrolling in any classes.","opts":["organize","identify","consider","familiarize"],"ans":"D","xp":"Chọn (D) familiarize\nGiải thích: Cấu trúc familiarize oneself with something (làm cho bản thân quen thuộc với cái gì/tìm hiểu kỹ về cái gì).\n(A) organize: tổ chức.\n(B) identify: nhận dạng.\n(C) consider: xem xét.\nDịch: Vui lòng tìm hiểu kỹ về chính sách hoàn trả học phí của công ty trước khi đăng ký bất kỳ lớp học nào."},{"n":115,"q":"The proposed purchase agreement is ------- being evaluated by officials at Corlan Tech.","opts":["active","actively","activity","activate"],"ans":"B","xp":"Chọn (B) actively\nGiải thích: Vị trí này nằm giữa trợ động từ \"is\" và động từ dạng bị động \"being evaluated\". Chúng ta cần một trạng từ.\n(A) active: Tính từ.\n(C) activity: Danh từ.\n(D) activate: Động từ.\nDịch: Thỏa thuận mua lại đề xuất hiện đang được các quan chức tại Corlan Tech tích cực đánh giá."},{"n":116,"q":"Another ------- option for getting to the airport will be available once the subway station at the international terminal is completed.","opts":["convenient","receptive","fortunate","traditional"],"ans":"A","xp":"Chọn (A) convenient\nGiải thích: Vị trí cần một tính từ bổ nghĩa cho danh từ \"option\" (lựa chọn). Xét về ngữ cảnh di chuyển ra sân bay bằng tàu điện ngầm, từ convenient (tiện lợi) là phù hợp nhất.\n(B) receptive: dễ tiếp thu/lĩnh hội.\n(C) fortunate: may mắn.\n(D) traditional: truyền thống.\nDịch: Một lựa chọn tiện lợi khác để đi đến sân bay sẽ sẵn sàng khi ga tàu điện ngầm tại nhà ga quốc tế được hoàn thành."},{"n":117,"q":"Given the forecast for rain on Saturday, the ceremony ------- indoors at the Raheen Gallery.","opts":["is held","was held","will be held","had been held"],"ans":"C","xp":"Chọn (C) will be held\nGiải thích: Câu có cụm \"Given the forecast for rain on Saturday\" (Dựa trên dự báo mưa vào thứ Bảy tới) cho thấy đây là một sự kiện trong tương lai. Vì buổi lễ (ceremony) không thể tự tổ chức nên ta dùng dạng bị động thì tương lai đơn.\nDịch: Dựa trên dự báo sẽ có mưa vào thứ Bảy, buổi lễ sẽ được tổ chức trong nhà tại Phòng triển lãm Raheen."},{"n":118,"q":"As Mr. Rzayev requested, the extra wood pallets have been stacked ------- the old warehouse.","opts":["between","across","over","behind"],"ans":"D","xp":"Chọn (D) behind\nGiải thích: Đây là câu về giới từ chỉ vị trí. Các tấm pallet gỗ được xếp chồng lên nhau ở phía sau (behind) là hợp lý nhất về mặt không gian.\n(A) between: ở giữa (phải giữa 2 vật).\n(B) across: băng qua.\n(C) over: phía trên (không tiếp xúc).\nDịch: Theo yêu cầu của ông Rzayev, các pallet gỗ bổ sung đã được xếp chồng phía sau nhà kho cũ."},{"n":119,"q":"Professor McNamara has published books on a ------- range of topics.","opts":["diversion","diversely","diverse","diversify"],"ans":"C","xp":"Chọn (C) diverse\nGiải thích: Vị trí này cần một tính từ đứng trước danh từ \"range\".\nCấu trúc a diverse range of + danh từ số nhiều (một loạt các... đa dạng).\nDịch: Giáo sư McNamara đã xuất bản nhiều cuốn sách về một loạt các chủ đề đa dạng."},{"n":120,"q":"A ------- of clearly defined milestones was likely why the software development project failed.","opts":["consent","break","lack","complex"],"ans":"C","xp":"Chọn (C) lack\nGiải thích: Cụm danh từ A lack of something (Sự thiếu hụt cái gì đó). Ngữ cảnh \"dự án thất bại\" (failed) phù hợp với việc \"thiếu các mốc thời gian rõ ràng\".\n(A) consent: sự đồng ý.\n(B) break: sự nghỉ ngơi/vỡ.\n(D) complex: khu phức hợp.\nDịch: Sự thiếu hụt các mốc thời gian được xác định rõ ràng có khả năng là lý do tại sao dự án phát triển phần mềm đã thất bại."},{"n":121,"q":"Rosemont Department Store employees are said to be very well-informed, -------, and responsive.","opts":["person","personably","personify","personable"],"ans":"D","xp":"Chọn (D) personable\nGiải thích: Vị trí này cần một tính từ để liệt kê cùng với \"well-informed\" và \"responsive\" nhằm mô tả tính cách nhân viên.\nDịch: Nhân viên của cửa hàng bách hóa Rosemont được cho là rất am hiểu, dễ mến và nhiệt tình."},{"n":122,"q":"The security officer at the front gate will ------- delivery drivers as to where to drop off packages.","opts":["invite","instruct","provide","present"],"ans":"B","xp":"Chọn (B) instruct\nGiải thích: Cấu trúc instruct someone as to/on something (hướng dẫn ai đó về việc gì). Nhân viên an ninh hướng dẫn tài xế nơi trả hàng.\n(A) invite: mời.\n(C) provide: cung cấp (thường là provide someone with something).\n(D) present: trình bày.\nDịch: Nhân viên an ninh tại cổng trước sẽ hướng dẫn các tài xế giao hàng về nơi để trả các kiện hàng."},{"n":123,"q":"------- some tickets to the concert are still available, all the best seats have already been taken.","opts":["Although","Except","Notice","After"],"ans":"A","xp":"Chọn (A) Although\nGiải thích: Đây là liên từ chỉ sự nhượng bộ (Mặc dù). Hai vế của câu có sự đối lập: \"vẫn còn vé\" và \"chỗ tốt nhất đã hết\".\n(B) Except: ngoại trừ (thường đi với \"for\").\n(C) Notice: thông báo (danh từ/động từ).\n(D) After: sau khi.\nDịch: Mặc dù một số vé cho buổi hòa nhạc vẫn còn, nhưng tất cả các chỗ ngồi tốt nhất đều đã được đặt hết."},{"n":124,"q":"Visitors must park in the designated parking area ------- risk having their vehicle towed.","opts":["or","but","yet","and"],"ans":"A","xp":"Chọn (A) or\nGiải thích: Liên từ or (hoặc/nếu không thì) được dùng ở đây để đưa ra một lời cảnh báo về hậu quả nếu không thực hiện hành động trước đó.\n(B) but: nhưng (chỉ sự đối lập).\n(C) yet: tuy nhiên.\n(D) and: và.\nDịch: Khách tham quan phải đậu xe trong khu vực đỗ xe đã được chỉ định, nếu không thì sẽ có nguy cơ bị kéo xe đi."},{"n":125,"q":"When Ms. Liu was hired, the ------- was to train her to work in the chemistry lab.","opts":["intend","intention","intended","intentional"],"ans":"B","xp":"Chọn (B) intention\nGiải thích: Vị trí này đứng sau mạo từ \"the\" nên cần một danh từ (Noun) đóng vai trò làm chủ ngữ của mệnh đề.\n(A) intend: động từ.\n(C) intended: động từ quá khứ/tính từ.\n(D) intentional: tính từ (cố ý).\nDịch: Khi bà Liu được thuê, mục đích (ý định) là đào tạo bà làm việc trong phòng thí nghiệm hóa học."},{"n":126,"q":"A ------- effect of increased tourism in our city has been rapid growth in the number of hospitality-related jobs.","opts":["tentative","negotiable","favorable","perceptive"],"ans":"C","xp":"Chọn (C) favorable\nGiải thích: Tính từ favorable (thuận lợi/có lợi) phù hợp về mặt ý nghĩa khi mô tả một tác động tích cực là \"sự tăng trưởng nhanh chóng của số lượng việc làm\".\n(A) tentative: tạm thời/ngập ngừng.\n(B) negotiable: có thể thương lượng.\n(D) perceptive: am hiểu/nhạy bén.\nDịch: Một tác động thuận lợi của việc gia tăng du lịch trong thành phố của chúng ta là sự tăng trưởng nhanh chóng về số lượng công việc liên quan đến ngành khách sạn."},{"n":127,"q":"The new payroll system will send an e-mail to employees ------- a manager edits their time sheet.","opts":["now that","or else","despite","whenever"],"ans":"D","xp":"Chọn (D) whenever\nGiải thích: Whenever (bất cứ khi nào) là liên từ chỉ thời gian, phù hợp để nói về một hành động tự động xảy ra mỗi khi có một điều kiện khác được thực hiện.\n(A) now that: vì giờ đây (chỉ nguyên nhân).\n(B) or else: nếu không thì.\n(C) despite: mặc dù (phải đi với danh từ/V-ing).\nDịch: Hệ thống bảng lương mới sẽ gửi email cho nhân viên bất cứ khi nào người quản lý chỉnh sửa bảng chấm công của họ."},{"n":128,"q":"The order of the speakers has been changed ------- Mr. Chen arrives late.","opts":["so","as of","during","in case"],"ans":"D","xp":"Chọn (D) in case\nGiải thích: Cấu trúc in case + mệnh đề (phòng khi/trong trường hợp) dùng để nói về việc chuẩn bị cho một tình huống có thể xảy ra.\n(A) so: vì vậy.\n(B) as of: kể từ (thường đi với mốc thời gian).\n(C) during: trong suốt (đi với danh từ).\nDịch: Thứ tự của các diễn giả đã được thay đổi phòng trường hợp ông Chen đến muộn."},{"n":129,"q":"Even though the fuel container can hold up to a ------- of ten liters, the manufacturer recommends putting in only nine.","opts":["maximum","potential","greatness","collection"],"ans":"A","xp":"Chọn (A) maximum\nGiải thích: Cụm từ a maximum of + số lượng (tối đa là bao nhiêu) dùng để chỉ giới hạn dung tích.\n(B) potential: tiềm năng.\n(C) greatness: sự to lớn/vĩ đại.\n(D) collection: bộ sưu tập.\nDịch: Mặc dù bình nhiên liệu có thể chứa tối đa mười lít, nhà sản xuất khuyến nghị chỉ nên đổ vào chín lít."},{"n":130,"q":"Ever since the Unicycle Café opened for business last May, it ------- weekly live music events.","opts":["to have hosted","has been hosting","was hosted","will be hosting"],"ans":"B","xp":"Chọn (B) has been hosting\nGiải thích: Dấu hiệu nhận biết là cụm từ Ever since (Kể từ khi). Khi một hành động bắt đầu trong quá khứ và kéo dài liên tục đến hiện tại, chúng ta sử dụng thì Hiện tại hoàn thành tiếp diễn (Present Perfect Continuous).\nDịch: Kể từ khi quán Café Unicycle khai trương vào tháng 5 năm ngoái, nơi này đã và đang tổ chức các sự kiện âm nhạc trực tiếp hàng tuần."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following advertisement.","passage":"<p>Do you fancy playing games with your mates? Do you enjoy tasty tea and snacks? If so, you won’t want to miss Game Night at Chez Tournoi. Each Friday from 6 to 10 P.M., Chez Tournoi welcomes you to its 44 Broad Avenue, Kingston, location for some fun and <span class=\"blank\" data-n=\"131\">-------</span>. Choose from our collection of board games, card games, trivia games, and more. <span class=\"blank\" data-n=\"132\">-------</span>. While you play, you can savour our freshly brewed tea, coffee, and hot chocolate <span class=\"blank\" data-n=\"133\">-------</span> our mouthwatering pastries. Game Night at Chez Tournoi is the perfect opportunity <span class=\"blank\" data-n=\"134\">-------</span> and socialise. Reserve your spot by ringing 01555-672212 or visiting www.cheztournoi.co.uk/gamenight.</p>","vi":"Bạn có thích chơi trò chơi cùng bạn bè không? Bạn có yêu thích trà ngon và các món ăn nhẹ không? Nếu có, bạn chắc chắn không nên bỏ lỡ Đêm Trò Chơi tại Chez Tournoi. Vào mỗi tối thứ Sáu từ 6 giờ đến 10 giờ tối, Chez Tournoi chào đón bạn tại địa điểm số 44 Broad Avenue, Kingston, để tận hưởng niềm vui và tiếng cười. Hãy lựa chọn từ bộ sưu tập các trò chơi bàn cờ, trò chơi bài, trò chơi đố vui (trivia) và nhiều trò khác nữa. Hoặc tự mang theo trò chơi của riêng bạn nếu bạn muốn. Trong khi chơi, bạn có thể thưởng thức trà, cà phê và sô-cô-la nóng mới pha, cũng như những loại bánh ngọt hấp dẫn của chúng tôi. Đêm Trò Chơi tại Chez Tournoi là cơ hội hoàn hảo để thư giãn và giao lưu. Hãy đặt chỗ trước bằng cách gọi 01555-672212 hoặc truy cập www.cheztournoi.co.uk/gamenight.","qs":[{"n":131,"opts":["cash","exercise","laughter","lessons"],"ans":"C","xp":"Chọn (C) laughter\nGiải thích: Câu trước nhắc đến \"fun\" (vui vẻ). Danh từ laughter (tiếng cười) tạo thành cụm \"fun and laughter\" rất phổ biến để mô tả bầu không khí giải trí tại một sự kiện trò chơi.\n(A) cash: tiền mặt (không phù hợp ngữ cảnh vui chơi).\n(B) exercise: tập thể dục (đây là chơi board game, không phải vận động mạnh).\n(D) lessons: bài học (quảng cáo nhấn mạnh sự giải trí, không phải học tập).\nDịch: Chez Tournoi chào đón bạn đến... để tận hưởng niềm vui và tiếng cười."},{"n":132,"opts":["Or bring your own if you prefer.","Vote for your favorite comedian.","The most popular drink is our caramel latte.","We also have several openings for servers."],"ans":"A","xp":"Chọn (A) Or bring your own if you prefer.\nGiải thích: Đoạn trước đó vừa liệt kê các loại trò chơi có sẵn tại địa điểm (board games, card games...). Câu (A) bổ sung thêm lựa chọn cho khách hàng là có thể mang theo trò chơi riêng của họ.\n(B) Bình chọn cho diễn viên hài yêu thích (không liên quan đến chơi game).\n(C) Đồ uống phổ biến nhất là latte caramel (câu tiếp theo mới bắt đầu nói về đồ uống, chèn vào đây sẽ bị ngắt mạch văn).\n(D) Có vị trí tuyển dụng bồi bàn (lạc đề so với nội dung mời khách đến chơi).\nDịch: \"Hãy chọn từ bộ sưu tập trò chơi bàn cờ, bài, đố vui của chúng tôi và nhiều hơn nữa. Hoặc tự mang theo trò chơi của riêng bạn nếu bạn muốn.\""},{"n":133,"opts":["in contrast to","furthermore","so that","as well as"],"ans":"D","xp":"Chọn (D) as well as\nGiải thích: Cấu trúc as well as dùng để nối các danh từ cùng loại, có nghĩa là \"cũng như là\". Ở đây dùng để liệt kê thêm món ăn bên cạnh các loại đồ uống đã nêu.\n(A) in contrast to: trái ngược với.\n(B) furthermore: hơn nữa (thường đứng đầu câu hoặc sau dấu chấm phẩy).\n(C) so that: để mà (chỉ mục đích, sau đó phải là một mệnh đề).\nDịch: \"Bạn có thể thưởng thức trà, cà phê và sô-cô-la nóng mới pha của chúng tôi cũng như là những món bánh ngọt hấp dẫn.\""},{"n":134,"opts":["is relaxing","to relax","relaxes","relaxation"],"ans":"B","xp":"Chọn (B) to relax\nGiải thích: Cấu trúc \"opportunity + to-V\" dùng để chỉ mục đích của một cơ hội.\nDịch: \"Đêm trò chơi tại Chez Tournoi là cơ hội hoàn hảo để thư giãn và giao lưu.\""}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Patton Henry &lt;p.henry@xmail.com&gt;</p><p><b>From:</b> Joanna Kanarak &lt;jkanarak@kanarakrealty.com&gt;</p><p><b>Date:</b> December 29</p><p><b>Subject:</b> Lease renewal</p></div><p>Dear Mr. Henry,</p><p>My records indicate that your lease is due to expire on March 31. If you wish to renew your <span class=\"blank\" data-n=\"135\">-------</span>, please let me know before January 31. If you do not reply to this e-mail, <span class=\"blank\" data-n=\"136\">-------</span> will assume that you do not wish to continue living in the 22 Fister Road property. <span class=\"blank\" data-n=\"137\">-------</span>, it will be listed as a rental available to a new tenant on April 1. If you want to move to an apartment larger or smaller than your current one, just let me know. <span class=\"blank\" data-n=\"138\">-------</span>.</p><p>Sincerely,</p><p>Joanna Kanarak, Kanarak Realty</p>","vi":"Gửi đến: Patton Henry <p.henry@xmail.com>\nTừ: Joanna Kanarak <jkanarak@kanarakrealty.com>\nNgày: 29 tháng 12\nTiêu đề: Gia hạn hợp đồng thuê\n\nKính gửi ông Henry,\n\nTheo hồ sơ của chúng tôi, hợp đồng thuê nhà của ông sẽ hết hạn vào ngày 31 tháng 3. Nếu ông muốn gia hạn hợp đồng của mình, vui lòng cho tôi biết trước ngày 31 tháng 1. Nếu ông không trả lời email này, tôi sẽ cho rằng ông không muốn tiếp tục sinh sống tại căn nhà số 22 đường Fister. Trong trường hợp đó, căn nhà này sẽ được niêm yết cho thuê và sẵn sàng cho người thuê mới vào ngày 1 tháng 4. Nếu ông muốn chuyển sang một căn hộ lớn hơn hoặc nhỏ hơn căn hộ hiện tại, chỉ cần cho tôi biết. Kanarak Realty rất hân hạnh được hỗ trợ ông bằng bất cứ cách nào có thể.\n\nTrân trọng,\n\nJoanna Kanarak, Công ty bất động sản Kanarak Realty","qs":[{"n":135,"opts":["license","contract","subscription","membership"],"ans":"B","xp":"Chọn (B) contract\nGiải thích: Trong ngữ cảnh thuê nhà và gia hạn hợp đồng (lease renewal), từ contract (hợp đồng) là từ phù hợp nhất để thay thế hoặc đi kèm với ý nghĩa của \"lease\".\n(A) license: giấy phép (thường dùng cho lái xe, kinh doanh).\n(C) subscription: sự đăng ký dài hạn (thường dùng cho báo chí, dịch vụ số).\n(D) membership: tư cách thành viên.\nDịch câu: \"Nếu ông muốn gia hạn hợp đồng của mình, vui lòng cho tôi biết trước ngày 31 tháng 1.\""},{"n":136,"opts":["I","they","some","everyone"],"ans":"A","xp":"Chọn (A) I\nGiải thích: Người gửi email là Joanna Kanarak, đại diện cho Kanarak Realty. Trong câu này, người viết đang nói về giả định của chính họ nếu không nhận được phản hồi, nên dùng đại từ I (tôi) là chính xác nhất.\nDịch câu: \"Nếu ông không phản hồi email này, tôi sẽ mặc định rằng ông không muốn tiếp tục sống tại căn hộ số 22 đường Fister.\""},{"n":137,"opts":["In any event","As expected","In that case","For instance"],"ans":"C","xp":"Chọn (C) In that case\nGiải thích: Cụm từ In that case (Trong trường hợp đó) dùng để chỉ hệ quả của giả định ở câu trước (trường hợp khách không phản hồi và không muốn thuê tiếp).\n(A) In any event: Trong bất cứ trường hợp nào/Dù sao đi nữa.\n(B) As expected: Như mong đợi.\n(D) For instance: Ví dụ là.\nDịch câu: \"Trong trường hợp đó, nó sẽ được liệt kê là căn hộ trống cho thuê cho người mới vào ngày 1 tháng 4.\""},{"n":138,"opts":["This business was started 22 years ago.","Kanarak Realty is happy to help you however we can.","You have occupied the current property for nearly two years.","Your apartment has three bedrooms and two bathrooms."],"ans":"B","xp":"Chọn (B) Kanarak Realty is happy to help you however we can.\nGiải thích: Câu trước đó đề cập đến việc nếu khách muốn chuyển sang căn hộ lớn hơn hoặc nhỏ hơn thì hãy báo cho người viết biết. Câu (B) khẳng định sự sẵn lòng hỗ trợ của công ty là lựa chọn logic nhất để kết lại email.\n(A) Doanh nghiệp bắt đầu 22 năm trước (thông tin không liên quan đến việc hỗ trợ thuê nhà hiện tại).\n(C) Bạn đã ở đây gần 2 năm (thông tin cá nhân không cần thiết phải nhắc lại ở cuối lời mời).\n(D) Căn hộ có 3 phòng ngủ (không phù hợp vì người viết đang nói chung về việc chuyển đổi căn hộ bất kỳ).\nDịch câu: \"Nếu ông muốn chuyển đến một căn hộ lớn hơn hoặc nhỏ hơn căn hiện tại, chỉ cần cho tôi biết. Kanarak Realty rất hân hạnh được hỗ trợ ông bằng bất cứ cách nào có thể.\""}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following brochure.","passage":"<h3><u>Where to Stay in Devegas</u></h3><p>The Devegas Peninsula features a wide range of <span class=\"blank\" data-n=\"139\">-------</span> options. More than twenty luxury hotels <span class=\"blank\" data-n=\"140\">-------</span> found along Devegas Beach, along with several moderately priced hotels in the Devegas Park neighborhood. <span class=\"blank\" data-n=\"141\">-------</span>, a range of small inns and short-term apartment rentals are scattered throughout the area. <span class=\"blank\" data-n=\"142\">-------</span>. Several inexpensive campsites and youth hostels are available throughout the year. For a detailed listing of vacation properties and hotels on the peninsula, see the back cover of this brochure.</p>","vi":"Nơi lưu trú tại Devegas\n\nBán đảo Devegas có rất nhiều lựa chọn chỗ ở. Hơn hai mươi khách sạn hạng sang có thể được tìm thấy dọc theo bãi biển Devegas, cùng với một số khách sạn có mức giá vừa phải trong khu vực công viên Devegas. Thêm vào đó, nhiều nhà trọ nhỏ và các căn hộ cho thuê ngắn hạn nằm rải rác khắp khu vực. Những du khách có ngân sách hạn chế cũng có các lựa chọn cho mình. Nhiều khu cắm trại giá rẻ và nhà nghỉ thanh niên hoạt động quanh năm. Để xem danh sách chi tiết các bất động sản nghỉ dưỡng và khách sạn trên bán đảo, vui lòng xem mặt sau của tờ quảng cáo này.","qs":[{"n":139,"opts":["dining","investment","entertainment","accommodation"],"ans":"D","xp":"Chọn (D) accommodation\nGiải thích: Cả đoạn văn đang liệt kê các lựa chọn về nơi ở như khách sạn (hotels), nhà nghỉ (inns), căn hộ cho thuê (apartment rentals). Do đó, danh từ tổng quát accommodation (chỗ ở) là chính xác nhất.\n(A) dining: ăn uống.\n(B) investment: đầu tư.\n(C) entertainment: giải trí.\nDịch: \"Bán đảo Devegas cung cấp đa dạng các lựa chọn về chỗ ở.\""},{"n":140,"opts":["were","can be","would be","have been"],"ans":"B","xp":"Chọn (B) can be\nGiải thích: Cấu trúc bị động can be found (có thể được tìm thấy) thường dùng trong các bài quảng cáo hoặc brochure hướng dẫn.\nDịch: \"Hơn hai mươi khách sạn sang trọng có thể được tìm thấy dọc theo bãi biển Devegas...\""},{"n":141,"opts":["After all","In addition","Fortunately","Nevertheless"],"ans":"B","xp":"Chọn (B) In addition\nGiải thích: Câu trước đã liệt kê các khách sạn sang trọng và khách sạn giá trung bình. Câu này liệt kê thêm các nhà nghỉ nhỏ và căn hộ. Vì vậy, ta dùng cụm từ nối In addition (Thêm vào đó) để bổ sung thông tin cùng loại.\n(A) After all: sau tất cả/xét cho cùng.\n(C) Fortunately: thật may mắn.\n(D) Nevertheless: tuy nhiên.\nDịch: \"Thêm vào đó, một loạt các nhà nghỉ nhỏ và căn hộ cho thuê ngắn hạn nằm rải rác khắp khu vực.\""},{"n":142,"opts":["Tourists flock to the peninsula during the summer months.","Plan your vacation while space remains available.","Travelers on a budget also have options.","The Devegas Peninsula is more than ten kilometers long."],"ans":"C","xp":"Chọn (C) Travelers on a budget also have options.\nGiải thích: Câu ngay sau ô trống đề cập đến \"inexpensive campsites and youth hostels\" (các khu cắm trại không đắt tiền và nhà trọ thanh niên). Đây là những lựa chọn dành cho người có ngân sách hạn chế. Câu (C) là phù hợp cho ý này.\n(A) Khách du lịch đổ xô đến vào mùa hè (không liên quan đến việc liệt kê loại hình chỗ ở giá rẻ phía sau).\n(B) Lên kế hoạch khi còn chỗ (câu kết thúc thúc giục, không phù hợp ở vị trí giữa đoạn liệt kê này).\n(D) Bán đảo dài hơn 10km (thông tin địa lý, không liên quan đến dịch vụ lưu trú).\nDịch: \"Những du khách có ngân sách hạn chế cũng có các lựa chọn cho mình. Một vài khu cắm trại không đắt tiền và nhà trọ thanh niên luôn sẵn có quanh năm.\""}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following notice.","passage":"<h3>Nelsign</h3><p><i>Your signature has been captured.</i></p><p><b>The document is waiting for four more signatures.</b></p><p>Once all parties have signed the Nelsign document, you will <span class=\"blank\" data-n=\"143\">-------</span> by e-mail. At that time, the sender will also receive an alert that all necessary signatures on the contract have been acquired. Upon <span class=\"blank\" data-n=\"144\">-------</span>, all signers may access and save the document. If you have a Nelsign account, this contract and any other documents you have previously signed electronically with Nelsign will be saved in your profile. <span class=\"blank\" data-n=\"145\">-------</span>. For any questions <span class=\"blank\" data-n=\"146\">-------</span> the signing process, contact our customer support center at inquiries@nelsign.com.</p>","vi":"Nelsign\n\nChữ ký của bạn đã được ghi nhận.\n\nTài liệu hiện đang chờ thêm bốn chữ ký nữa.\n\nKhi tất cả các bên đã ký vào tài liệu Nelsign, bạn sẽ được thông báo qua email. Vào thời điểm đó, người gửi cũng sẽ nhận được thông báo rằng tất cả các chữ ký cần thiết trên hợp đồng đã được thu thập. Sau khi hoàn tất, tất cả những người ký có thể truy cập và lưu tài liệu. Nếu bạn có tài khoản Nelsign, hợp đồng này và bất kỳ tài liệu nào khác mà bạn đã ký điện tử trước đây bằng Nelsign sẽ được lưu trong hồ sơ của bạn. Đối với những người cần tạo tài khoản, chỉ cần truy cập trang web của chúng tôi. Nếu bạn có bất kỳ câu hỏi nào liên quan đến quy trình ký kết, vui lòng liên hệ trung tâm hỗ trợ khách hàng của chúng tôi qua địa chỉ inquiries@nelsign.com.","qs":[{"n":143,"opts":["notify","be notified","notifying","have notified"],"ans":"B","xp":"Chọn (B) be notified\nGiải thích: Sau từ \"you will\" chúng ta cần một động từ nguyên mẫu. Dựa vào ngữ cảnh, bạn (người dùng) là đối tượng nhận thông báo từ hệ thống qua email khi các bên đã ký xong, do đó câu này phải ở thể bị động (will + be + V3/ed).\nDịch câu: \"Khi tất cả các bên đã ký vào tài liệu Nelsign, bạn sẽ được thông báo qua email.\""},{"n":144,"opts":["complete","completed","completely","completion"],"ans":"D","xp":"Chọn (D) completion\nGiải thích: Đứng sau giới từ \"Upon\" chúng ta cần một danh từ hoặc V-ing để chỉ một sự kiện vừa mới kết thúc. Upon completion = sau khi hoàn tất.\n(A) complete: động từ/tính từ.\n(B) completed: động từ quá khứ/tính từ.\n(C) completely: trạng từ.\nDịch câu: \"Sau khi hoàn tất, tất cả những người ký tên có thể truy cập và lưu tài liệu.\""},{"n":145,"opts":["For those who need to create an account, simply visit our Web site.","The contract’s effective date appears at the top of the document.","The privacy terms are attached to the contract.","Our company is located in Utah."],"ans":"A","xp":"Chọn (A) For those who need to create an account, simply visit our Web site.\nGiải thích: Câu phía trước đang nói về lợi ích khi có tài liệu được lưu trong hồ sơ cá nhân nếu bạn có một \"Nelsign account\". Vì vậy, câu tiếp theo (A) hướng dẫn cách để tạo tài khoản đó là một sự liên kết nội dung rất chặt chẽ.\n(B) Ngày hiệu lực của hợp đồng (không liên quan đến việc hướng dẫn sử dụng phần mềm).\n(C) Các điều khoản quyền riêng tư (quá chi tiết, không phải trọng tâm thông báo này).\n(D) Công ty đặt tại Utah (thông tin ngoài lề, không giúp ích cho quy trình ký).\nDịch câu: \"Đối với những người cần tạo tài khoản, chỉ cần truy cập trang web của chúng tôi.\""},{"n":146,"opts":["around","through","regarding","assuming"],"ans":"C","xp":"Chọn (C) regarding\nGiải thích: Giới từ regarding có nghĩa là \"về việc/liên quan đến\". Cụm từ \"questions regarding the signing process\" (những câu hỏi liên quan đến quy trình ký kết) là cách diễn đạt chuyên nghiệp và phổ biến nhất.\n(A) around: xung quanh (nghĩa đen về khoảng cách).\n(B) through: xuyên qua/thông qua.\n(D) assuming: giả sử (động từ).\nDịch câu: \"Đối với bất kỳ câu hỏi nào liên quan đến quy trình ký kết, hãy liên hệ với trung tâm hỗ trợ khách hàng của chúng tôi...\""}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following coupon.","passages":["<h3>COUPON</h3><p>If you love the delicious cheese and crackers served at Truli Cafés, you can now enjoy this popular snack at home! Truli crackers and cheese are now available at major supermarkets.</p><p>Save $2.00 on the purchase of ONE box of Truli crackers (any size) when you buy any TWO packages of Truli cheese.</p><p>Limit one coupon per customer. This coupon may not be combined with other special offers.</p><p>Expires July 31.</p>"],"vi":"PHIẾU GIẢM GIÁ\n\nNếu bạn yêu thích món phô mai và bánh quy giòn thơm ngon được phục vụ tại các quán cà phê Truli, giờ đây bạn có thể thưởng thức món ăn vặt phổ biến này ngay tại nhà! Bánh quy và phô mai Truli hiện đã có mặt tại các siêu thị lớn.\n\nGiảm 2,00 đô la khi mua MỘT hộp bánh quy Truli (bất kỳ kích cỡ nào) khi bạn mua HAI gói phô mai Truli bất kỳ.\n\nMỗi khách hàng chỉ được sử dụng một phiếu giảm giá. Phiếu này không được dùng chung với các chương trình khuyến mãi khác.\n\nHết hạn vào ngày 31 tháng 7.","qs":[{"n":147,"q":"What is indicated about boxes of Truli crackers?","qvi":"Điều gì được cho biết về các hộp bánh quy Truli?","opts":["They come in various sizes.","They are available in several flavors.","They are sold exclusively at Truli Cafés.","They cost $2.00 more than a package of Truli cheese."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"Save $2.00 on the purchase of ONE box of Truli crackers (any size)\" (Giảm 2 đô khi mua MỘT hộp bánh quy Truli (bất kỳ kích cỡ nào)) → bánh quy có nhiều kích cỡ. (C) sai vì bánh đã có ở các siêu thị lớn.\n(A) Chúng có nhiều kích cỡ khác nhau.\n(B) Chúng có nhiều hương vị.\n(C) Chúng chỉ được bán tại các quán Truli Café.\n(D) Chúng đắt hơn 2 đô so với một gói phô mai Truli."},{"n":148,"q":"What is indicated about the coupon?","qvi":"Điều gì được cho biết về phiếu giảm giá?","opts":["It can be used more than once.","It requires the purchase of another product.","It can be used for buying hot drinks.","It must be used before July 1."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"...when you buy any TWO packages of Truli cheese\" (khi bạn mua HAI gói phô mai Truli bất kỳ) → phải mua kèm sản phẩm khác (phô mai) mới được giảm giá. (A) sai: \"Limit one coupon per customer\"; (D) sai: hết hạn ngày 31/7.\n(A) Có thể dùng nhiều lần.\n(B) Cần mua kèm một sản phẩm khác.\n(C) Có thể dùng để mua đồ uống nóng.\n(D) Phải sử dụng trước ngày 1 tháng 7."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following text message.","passages":["<h4>Brice’s Ice Creamery</h4><p>June 29, 2:02 P.M.</p><p>Thank you, Nathan Thielen, for joining Brice’s Ice Creamery’s rewards program. You have earned your first points just by signing up for our program.</p><p>For every $1.00 you spend in one of our ice cream shops, you earn 1 point. Every 100 points you earn can be redeemed for $5.00 off your purchase of ice cream or store merchandise, including T-shirts and tote bags. You are even entitled to a free scoop at any Brice’s Ice Creamery on your birthday.</p><p><b>You have earned: 20</b> points. You are <b>80</b> points away from earning your next reward.</p>"],"vi":"Brice’s Ice Creamery\n\nNgày 29 tháng 6, 2:02 chiều\n\nCảm ơn bạn, Nathan Thielen, đã tham gia chương trình khách hàng thân thiết của Brice’s Ice Creamery. Bạn đã nhận được những điểm thưởng đầu tiên chỉ bằng cách đăng ký tham gia chương trình của chúng tôi.\n\nVới mỗi 1,00 đô la bạn chi tiêu tại một trong các cửa hàng kem của chúng tôi, bạn sẽ nhận được 1 điểm. Mỗi 100 điểm bạn tích lũy được có thể đổi lấy 5,00 đô la giảm giá cho việc mua kem hoặc các sản phẩm của cửa hàng, bao gồm áo thun và túi vải. Ngoài ra, bạn còn được tặng một viên kem miễn phí tại bất kỳ cửa hàng Brice’s Ice Creamery nào vào ngày sinh nhật của bạn.\n\nBạn đã tích lũy được: 20 điểm. Bạn còn cần 80 điểm nữa để nhận phần thưởng tiếp theo.","qs":[{"n":149,"q":"What does the text message indicate about Brice's Ice Creamery?","qvi":"Tin nhắn cho biết điều gì về cửa hàng kem Brice’s Ice Creamery?","opts":["It has more than one location.","It rents space for birthday parties.","It sells ice cream cones for $5.00 each.","It rewards customers for referring friends."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"For every $1.00 you spend in one of our ice cream shops\" (tại một trong các cửa hàng kem của chúng tôi) và \"at any Brice’s Ice Creamery\" (tại bất kỳ cửa hàng nào) → có nhiều chi nhánh.\n(A) Cửa hàng có hơn một chi nhánh.\n(B) Có dịch vụ cho thuê không gian tổ chức tiệc sinh nhật.\n(C) Bán kem ốc quế với giá 5 đô mỗi cây.\n(D) Thưởng điểm cho khách hàng khi giới thiệu bạn bè."},{"n":150,"q":"What did Mr. Thielen receive for signing up for the rewards program?","qvi":"Ông Thielen đã nhận được gì khi đăng ký chương trình tích điểm?","opts":["1 point","20 points","80 points","100 points"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"You have earned your first points just by signing up\" (Bạn nhận được những điểm đầu tiên chỉ bằng việc đăng ký) + \"You have earned: 20 points\" → ông nhận được 20 điểm khi đăng ký.\n(A) 1 điểm\n(B) 20 điểm\n(C) 80 điểm\n(D) 100 điểm"}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Charlie Tran &lt;Charlie.Tran@mailcrate.com&gt;</p><p><b>From:</b> Grace Drance &lt;GDrance@hoppersmedicalcenter.org&gt;</p><p><b>Date:</b> January 10</p><p><b>Subject:</b> Missed appointment</p></div><p>Dear Mr. Tran,</p><p>I am contacting you because you did not appear for your 1:00 p.m. appointment for your annual physical exam at Hopper’s Medical Center (HMC) today. As you know, it is our policy to charge the full appointment fee for missed appointments unless the patient notifies us at least 24 hours in advance of the scheduled visit.</p><p>However, we are waiving the fee because this is your first missed appointment in fifteen years of being a patient at the center. Please contact the office as soon as possible to reschedule your appointment. Your physician, Dr. Ramanathan, has created additional appointment times this month because he will be on vacation in February.</p><p>Sincerely,</p><p>Grace Drance, Scheduling Assistant</p>"],"vi":"Gửi đến: Charlie Tran <Charlie.Tran@mailcrate.com>\nTừ: Grace Drance <GDrance@hoppersmedicalcenter.org>\nNgày: 10 tháng 1\nChủ đề: Lỡ hẹn khám\n\nKính gửi ông Tran,\n\nTôi liên hệ với ông vì hôm nay ông đã không đến buổi hẹn lúc 1:00 chiều cho kỳ khám sức khỏe định kỳ hằng năm của ông tại Trung tâm Y tế Hopper (HMC). Như ông đã biết, chính sách của chúng tôi là thu đầy đủ phí hẹn khám đối với các trường hợp vắng mặt không báo trước, trừ khi bệnh nhân thông báo cho chúng tôi ít nhất 24 giờ trước thời gian hẹn đã được lên lịch.\n\nTuy nhiên, chúng tôi miễn khoản phí này vì đây là lần đầu tiên ông lỡ hẹn trong 15 năm ông là bệnh nhân của trung tâm. Vui lòng liên hệ với văn phòng sớm nhất có thể để đặt lại lịch hẹn. Bác sĩ của ông, bác sĩ Ramanathan, đã bổ sung thêm các khung giờ hẹn trong tháng này vì ông ấy sẽ đi nghỉ vào tháng Hai.\n\nTrân trọng,\n\nGrace Drance, Trợ lý sắp xếp lịch hẹn","qs":[{"n":151,"q":"What is one purpose of the e-mail?","qvi":"Một mục đích của e-mail là gì?","opts":["To remind a patient of an upcoming appointment","To recommend that an appointment be rescheduled","To inform a patient that a fee has been charged","To provide a patient with the results of a recent physical exam"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Please contact the office as soon as possible to reschedule your appointment\" (Vui lòng liên hệ văn phòng sớm nhất có thể để đặt lại lịch hẹn). (C) sai vì \"we are waiving the fee\" (chúng tôi miễn phí).\n(A) Nhắc bệnh nhân về một buổi hẹn sắp tới.\n(B) Đề nghị dời lịch hẹn (đặt lại lịch hẹn).\n(C) Thông báo bệnh nhân đã bị tính phí.\n(D) Cung cấp kết quả khám sức khỏe gần đây cho bệnh nhân."},{"n":152,"q":"What is indicated about Dr. Ramanathan?","qvi":"Điều gì được cho biết về bác sĩ Ramanathan?","opts":["He will be taking time off soon.","He is a longtime friend of Mr. Tran.","He earned his medical degree 24 years ago.","He is relocating his practice in February."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"...because he will be on vacation in February\" (vì ông ấy sẽ đi nghỉ vào tháng Hai) → be on vacation = take time off; email viết ngày 10/1 nên tháng Hai là \"soon\".\n(A) Ông ấy sắp nghỉ phép.\n(B) Ông là bạn lâu năm của ông Tran.\n(C) Ông đã lấy bằng y khoa 24 năm trước.\n(D) Ông sẽ chuyển phòng khám vào tháng Hai."}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Kanae Ikeda (5:46 P.M.)</b></p><p>Hi, Anders. Are you still in the office by any chance?</p></div><div class=\"msg\"><p><b>Anders Lorck (5:48 P.M.)</b></p><p>I was just packing up.</p></div><div class=\"msg\"><p><b>Kanae Ikeda (5:50 P.M.)</b></p><p>Thank goodness! Could you do me a favour and adjust the temperature setting on the office thermostat down to 20° on your way out? The custodian is out today, and I was supposed to do it. Unfortunately, I’m on a train to Melbourne for the weekend.</p></div><div class=\"msg\"><p><b>Anders Lorck (5:51 P.M.)</b></p><p>I’ll take care of it right now. Enjoy your time in Melbourne!</p></div><div class=\"msg\"><p><b>Kanae Ikeda (5:52 P.M.)</b></p><p>Thanks. I definitely will.</p></div>"],"vi":"Kanae Ikeda (5:46 chiều): Chào Anders. Anh còn ở văn phòng không?\n\nAnders Lorck (5:48 chiều): Tôi vừa mới thu dọn đồ để về.\n\nKanae Ikeda (5:50 chiều): May quá! Anh có thể giúp tôi một việc và điều chỉnh nhiệt độ của bộ điều nhiệt văn phòng xuống 20° trước khi anh ra về được không? Hôm nay nhân viên vệ sinh nghỉ, và lẽ ra tôi phải làm việc đó. Nhưng thật không may, tôi đang trên tàu đi Melbourne cho kỳ nghỉ cuối tuần.\n\nAnders Lorck (5:51 chiều): Tôi sẽ lo việc đó ngay bây giờ. Chúc bạn có thời gian vui vẻ ở Melbourne!\n\nKanae Ikeda (5:52 chiều): Cảm ơn anh. Chắc chắn tôi sẽ vậy.","qs":[{"n":153,"q":"At 5:48 P.M., what does Mr. Lorck imply when he writes, “I was just packing up”?","qvi":"Lúc 5:48 chiều, ông Lorck ngụ ý điều gì khi viết “Tôi vừa mới thu dọn đồ”?","opts":["He is preparing for a trip.","He has not yet left the office.","He must return some important documents.","He plans to work late this evening."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Cô Ikeda hỏi \"Are you still in the office by any chance?\" (Anh còn ở văn phòng không?) → ông trả lời \"I was just packing up\" (đang dọn đồ chuẩn bị về) = vẫn còn ở văn phòng. Cô đáp \"Thank goodness!\" (May quá!).\n(A) Ông đang chuẩn bị cho một chuyến đi.\n(B) Ông vẫn chưa rời văn phòng.\n(C) Ông phải trả lại một số tài liệu quan trọng.\n(D) Ông dự định làm việc muộn tối nay."},{"n":154,"q":"What is most likely true about Ms. Ikeda?","qvi":"Điều nào có khả năng đúng nhất về cô Ikeda?","opts":["She forgot to perform a task.","She usually works from home.","She regularly travels to Melbourne.","She thinks the office is too cold."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"The custodian is out today, and I was supposed to do it. Unfortunately, I’m on a train to Melbourne\" (lẽ ra tôi phải làm việc đó, nhưng tôi đang trên tàu đi Melbourne) → cô đã quên điều chỉnh bộ điều nhiệt trước khi về. (D) sai vì cô muốn giảm nhiệt độ.\n(A) Cô quên làm một việc gì đó.\n(B) Cô thường làm việc tại nhà.\n(C) Cô hay đi Melbourne.\n(D) Cô thấy văn phòng quá lạnh."}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following Web page.","passages":["<p>https://www.qualitekkresearch.com/aboutus</p><p><b>Home | About Us | Register | Testimonials</b></p><p>Thousands of large companies use surveys to measure customer satisfaction with the goal of improving their business. Qualitekk Research serves its client companies by analyzing survey results and producing detailed reports containing insights about customers’ preferences. — <span class=\"pos\">[1]</span> —. Over twelve years of operation, Qualitekk Research has built a strong reputation for providing valuable data.</p><p>Every day, consumers complete more than 20,000 online surveys that provide feedback on hundreds of different products. — <span class=\"pos\">[2]</span> —. We connect consumers with surveys about products that may interest them. Participants who submit a survey that we facilitate will earn reward points from us. After as few as five surveys, points can be redeemed for a gift card usable at many stores. — <span class=\"pos\">[3]</span> —.</p><p>If you would like to join, visit our Register page and complete the member profile questionnaire. This information will help us identify surveys that match your interests. We will then send you links to those surveys to complete at your leisure. If your interests change, simply update your profile. — <span class=\"pos\">[4]</span> —. All responses in Qualitekk Research surveys are confidential, and you will never be personally identified with survey data.</p>"],"vi":"https://www.qualitekkresearch.com/aboutus\nTrang chủ | Về chúng tôi | Đăng ký | Đánh giá của khách hàng\n\nHàng nghìn công ty lớn sử dụng khảo sát để đo lường mức độ hài lòng của khách hàng với mục tiêu cải thiện hoạt động kinh doanh. Qualitekk Research phục vụ các công ty khách hàng bằng cách phân tích kết quả khảo sát và lập các báo cáo chi tiết chứa đựng những thông tin chuyên sâu về sở thích của khách hàng. — [1] — Trong hơn mười hai năm hoạt động, Qualitekk Research đã xây dựng được danh tiếng vững chắc trong việc cung cấp dữ liệu có giá trị.\n\nMỗi ngày, người tiêu dùng hoàn thành hơn 20.000 khảo sát trực tuyến, cung cấp phản hồi về hàng trăm sản phẩm khác nhau. — [2] — Chúng tôi kết nối người tiêu dùng với các khảo sát về những sản phẩm có thể họ quan tâm. Những người tham gia gửi khảo sát do chúng tôi hỗ trợ sẽ nhận được điểm thưởng từ chúng tôi. Chỉ sau ít nhất năm khảo sát, số điểm này có thể được đổi lấy thẻ quà tặng sử dụng tại nhiều cửa hàng. — [3] —\n\nNếu bạn muốn tham gia, hãy truy cập trang Register (Đăng ký) và hoàn thành bảng câu hỏi hồ sơ thành viên. Thông tin này sẽ giúp chúng tôi xác định những khảo sát phù hợp với mối quan tâm của bạn. Sau đó, chúng tôi sẽ gửi cho bạn đường link đến các khảo sát để bạn hoàn thành vào thời gian rảnh. Nếu sở thích của bạn thay đổi, chỉ cần cập nhật hồ sơ cá nhân. — [4] — Tất cả các phản hồi trong khảo sát của Qualitekk Research đều được bảo mật, và bạn sẽ không bao giờ bị nhận diện cá nhân thông qua dữ liệu khảo sát.","qs":[{"n":155,"q":"What is indicated about Qualitekk Research?","qvi":"Điều gì được cho biết về Qualitekk Research?","opts":["It recently revised its Web site.","It has won awards for its services.","It produces reports for companies.","It has been in business for twenty years."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Qualitekk Research serves its client companies by analyzing survey results and producing detailed reports\" (phục vụ các công ty khách hàng bằng cách phân tích kết quả khảo sát và lập báo cáo chi tiết). (D) sai: \"Over twelve years of operation\" (12 năm).\n(A) Họ vừa cập nhật trang web.\n(B) Họ đã từng thắng giải cho dịch vụ của mình.\n(C) Họ tạo báo cáo cho các công ty.\n(D) Họ đã hoạt động trong 20 năm."},{"n":156,"q":"What are Qualitekk Research’s participants encouraged to do?","qvi":"Những người tham gia khảo sát của Qualitekk Research được khuyến khích làm gì?","opts":["Write their own survey questions","Persuade their friends to register","Submit photos of preferred products","Update their member profiles if necessary"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: \"If your interests change, simply update your profile\" (Nếu sở thích của bạn thay đổi, chỉ cần cập nhật hồ sơ cá nhân) → if necessary = if your interests change.\n(A) Tự viết câu hỏi khảo sát của họ\n(B) Rủ bạn bè đăng ký\n(C) Gửi ảnh các sản phẩm yêu thích\n(D) Cập nhật hồ sơ thành viên nếu cần"},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“These numbers continue to grow as online commerce increases.”","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n“Những con số này tiếp tục tăng khi thương mại trực tuyến phát triển.”","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Phía trước vị trí [2] là câu \"Every day, consumers complete more than 20,000 online surveys that provide feedback on hundreds of different products\" (Mỗi ngày, người tiêu dùng hoàn thành hơn 20.000 khảo sát trực tuyến, phản hồi về hàng trăm sản phẩm). \"These numbers\" (những con số này) chỉ con số 20.000 khảo sát / hàng trăm sản phẩm → câu chèn nói tiếp về số lượng khảo sát đang tăng."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following memo.","passages":["<h3>MEMO</h3><div class=\"hdr\"><p><b>To:</b> Swansea Spotlight Theatre staff</p><p><b>From:</b> Rhian Griffud, Chief Executive</p><p><b>Date:</b> 7 September</p><p><b>Subject:</b> What’s happening</p></div><p>Dear Staff:</p><p>I am thrilled about the imminent reopening of our theatre, and I hope you are too. It has been a long process, and audiences will undoubtedly appreciate all the renovations, including the newly upholstered seats and the updated heating and air-conditioning system. I believe that all of us who work in the theatre will enjoy the changes as well. I know you must be eager to rehearse in the newly refurbished building next week.</p><p>One of the more visible updates to the space is the Swansea Spotlight Bistro, a new restaurant with a large seating area that replaces our previous concession stand. The bistro faces the street and will be open to the public even when no performances are scheduled. The menu will feature a wide selection of beverages, snacks, and meals, and it will change with the seasons to highlight locally available products.</p><p>On 2 October, we will celebrate the theatre’s grand reopening with a one-night musical showcase starring some of the best actors and singers in Wales. One week later, we will begin the run of <i>Blake’s River</i>. I appreciate all your hard work and patience as we start this new chapter in the history of Swansea Spotlight Theatre, and I look forward to our exciting future together.</p>"],"vi":"BẢN GHI NHỚ\n\nGửi đến: Nhân viên Nhà hát Swansea Spotlight\nTừ: Rhian Griffud, Giám đốc điều hành\nNgày: 7 tháng 9\nChủ đề: Những điều sắp diễn ra\n\nGửi toàn thể nhân viên,\n\nTôi vô cùng phấn khởi trước việc nhà hát của chúng ta sắp được mở cửa trở lại, và tôi hy vọng các bạn cũng vậy. Đây là một quá trình dài, và khán giả chắc chắn sẽ đánh giá cao tất cả các hạng mục cải tạo, bao gồm ghế ngồi mới được bọc lại cũng như hệ thống sưởi và điều hòa không khí được nâng cấp. Tôi tin rằng tất cả chúng ta làm việc tại nhà hát cũng sẽ hài lòng với những thay đổi này. Tôi biết các bạn hẳn đang mong chờ được tập dượt trong tòa nhà mới được tân trang vào tuần tới.\n\nMột trong những thay đổi dễ nhận thấy nhất của không gian là Swansea Spotlight Bistro, một nhà hàng mới với khu vực chỗ ngồi rộng rãi, thay thế cho quầy bán đồ ăn nhẹ trước đây. Quán bistro này hướng ra mặt phố và sẽ mở cửa cho công chúng ngay cả khi không có buổi biểu diễn nào được lên lịch. Thực đơn sẽ bao gồm nhiều loại đồ uống, món ăn nhẹ và bữa ăn, và sẽ thay đổi theo mùa nhằm tôn vinh các sản phẩm có sẵn tại địa phương.\n\nVào ngày 2 tháng 10, chúng ta sẽ kỷ niệm lễ khai trương lớn của nhà hát bằng một buổi trình diễn âm nhạc kéo dài một đêm, với sự tham gia của một số diễn viên và ca sĩ xuất sắc nhất xứ Wales. Một tuần sau, chúng ta sẽ bắt đầu công diễn vở Blake’s River. Tôi trân trọng tất cả sự chăm chỉ và kiên nhẫn của các bạn khi chúng ta bước sang chương mới trong lịch sử của Nhà hát Swansea Spotlight, và tôi mong chờ một tương lai đầy hứng khởi của chúng ta cùng nhau.","qs":[{"n":158,"q":"What is the purpose of the memo?","qvi":"Mục đích của bản ghi nhớ là gì?","opts":["To announce a collaboration with another theater group","To update employees about the completion of a project","To schedule some rehearsal spaces","To report on problems with a heating and cooling system"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"I am thrilled about the imminent reopening of our theatre... It has been a long process... all the renovations\" (sắp mở cửa trở lại, quá trình cải tạo dài đã xong) → thông báo cho nhân viên về việc dự án cải tạo đã hoàn thành.\n(A) Thông báo hợp tác với một nhóm kịch khác\n(B) Cập nhật cho nhân viên về việc hoàn thành một dự án\n(C) Sắp xếp các không gian tập luyện\n(D) Báo cáo vấn đề liên quan đến hệ thống sưởi và làm mát"},{"n":159,"q":"What is indicated about the Swansea Spotlight Bistro?","qvi":"Điều gì được cho biết về Swansea Spotlight Bistro?","opts":["It will feature a fixed menu.","It will be open only during performances.","It replaces a concession stand.","It needs more tables and chairs."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"...a new restaurant with a large seating area that replaces our previous concession stand\" (nhà hàng mới thay thế quầy bán đồ ăn nhẹ trước đây). (A) sai: menu \"will change with the seasons\"; (B) sai: mở cửa \"even when no performances are scheduled\".\n(A) Sẽ có thực đơn cố định.\n(B) Chỉ mở cửa trong thời gian diễn ra buổi diễn.\n(C) Nó thay thế quầy bán đồ ăn nhẹ trước đây.\n(D) Cần thêm bàn ghế."},{"n":160,"q":"What is mentioned about October 2?","qvi":"Điều gì được nhắc đến về ngày 2 tháng 10?","opts":["A single performance of a show will take place.","Town officials will attend an event.","Blake’s River will begin its run.","New costumes will be delivered for an upcoming play."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: \"On 2 October, we will celebrate the theatre’s grand reopening with a one-night musical showcase\" (buổi trình diễn âm nhạc chỉ một đêm) → one-night = a single performance. (C) sai: Blake’s River bắt đầu \"One week later\" (một tuần sau).\n(A) Chỉ có một buổi biểu diễn duy nhất của một chương trình diễn ra.\n(B) Các quan chức thị trấn sẽ tham dự sự kiện.\n(C) Vở Blake’s River sẽ bắt đầu được công diễn.\n(D) Trang phục mới sẽ được giao cho vở diễn sắp tới."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following company Web page.","passages":["<h3>Join the Building Blocks Team</h3><p>Building Blocks is the newest employee-led volunteer group at Milos Tek Corporation. Unlike other company groups that organize charity fund-raisers or clean up local parks, Building Blocks asks its members to share their professional expertise with others. We offer free seminars on management, public relations, grant writing, and various types of application software to nonprofit organizations in Lalortown. These organizations include youth clubs, community sports leagues, the Lalortown Nature Center, and Lalortown’s public radio station!</p><p>Participation in Building Blocks generally involves more time than what is encouraged by other volunteer groups at Milos Tek. While each seminar is typically one hour long, planning and preparation are also part of our activities. Those who choose to volunteer with us can expect to dedicate about two hours each week to our work.</p><p>We will hold a 30-minute information session on Friday, May 3, at 12:30 P.M., in conference room B-2. In the meantime, if you have questions, please contact Min-Gyu Byun at byun003@milostek.com.</p>"],"vi":"Tham gia nhóm Building Blocks\n\nBuilding Blocks là nhóm tình nguyện do nhân viên dẫn dắt mới nhất tại Tập đoàn Milos Tek. Không giống như các nhóm khác trong công ty thường tổ chức gây quỹ từ thiện hoặc dọn dẹp công viên địa phương, Building Blocks đề nghị các thành viên chia sẻ chuyên môn nghề nghiệp của mình với người khác. Chúng tôi cung cấp các buổi hội thảo miễn phí về quản lý, quan hệ công chúng, viết đề xuất xin tài trợ, và nhiều loại phần mềm ứng dụng khác nhau cho các tổ chức phi lợi nhuận tại Lalortown. Các tổ chức này bao gồm các câu lạc bộ thanh thiếu niên, các giải thể thao cộng đồng, Trung tâm Thiên nhiên Lalortown, và đài phát thanh công cộng của Lalortown!\n\nViệc tham gia Building Blocks thường đòi hỏi nhiều thời gian hơn so với mức được khuyến khích ở các nhóm tình nguyện khác tại Milos Tek. Mặc dù mỗi buổi hội thảo thường kéo dài một giờ, nhưng việc lên kế hoạch và chuẩn bị cũng là một phần trong các hoạt động của chúng tôi. Những ai chọn tình nguyện cùng chúng tôi có thể dự kiến dành khoảng hai giờ mỗi tuần cho công việc này.\n\nChúng tôi sẽ tổ chức một buổi cung cấp thông tin kéo dài 30 phút vào thứ Sáu, ngày 3 tháng 5, lúc 12:30 trưa, tại phòng họp B-2. Trong thời gian chờ đợi, nếu bạn có câu hỏi, vui lòng liên hệ Min-Gyu Byun qua địa chỉ byun003@milostek.com.","qs":[{"n":161,"q":"For whom is the information most likely intended?","qvi":"Thông tin này có khả năng dành cho ai nhất?","opts":["Lalortown residents who work for nonprofit organizations","Lalortown residents who are changing careers","Milos Tek employees who want to help the local community","Milos Tek employees who want to mentor newly hired staff members"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Building Blocks is the newest employee-led volunteer group at Milos Tek Corporation\" (nhóm tình nguyện do nhân viên Milos Tek dẫn dắt) + tiêu đề \"Join the Building Blocks Team\" + hỗ trợ các tổ chức phi lợi nhuận ở Lalortown → dành cho nhân viên Milos Tek muốn giúp cộng đồng địa phương.\n(A) Cư dân Lalortown làm việc cho tổ chức phi lợi nhuận\n(B) Cư dân Lalortown đang chuyển nghề\n(C) Nhân viên Milos Tek muốn hỗ trợ cộng đồng địa phương\n(D) Nhân viên Milos Tek muốn hướng dẫn nhân viên mới"},{"n":162,"q":"What is the main activity performed by Building Blocks?","qvi":"Hoạt động chính mà Building Blocks thực hiện là gì?","opts":["Developing radio programming","Planning fund-raisers","Presenting informational sessions","Organizing job fairs"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"We offer free seminars on management, public relations, grant writing, and various types of application software\" (Chúng tôi cung cấp các buổi hội thảo miễn phí...) → seminars = informational sessions. (B) sai: gây quỹ là việc của các nhóm khác.\n(A) Phát triển chương trình radio\n(B) Lên kế hoạch gây quỹ\n(C) Tổ chức/trình bày các buổi cung cấp thông tin\n(D) Tổ chức hội chợ việc làm"},{"n":163,"q":"What is required of Building Blocks members?","qvi":"Thành viên Building Blocks bắt buộc phải làm gì?","opts":["They must be residents of Lalortown.","They must give a fairly large amount of time.","They must hold advanced academic degrees.","They must attend a day-long seminar each month."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: \"Participation in Building Blocks generally involves more time than what is encouraged by other volunteer groups... dedicate about two hours each week\" (đòi hỏi nhiều thời gian hơn các nhóm khác, khoảng 2 giờ mỗi tuần).\n(A) Phải là cư dân Lalortown\n(B) Phải dành khá nhiều thời gian\n(C) Phải có bằng cấp học thuật cao\n(D) Phải tham dự hội thảo kéo dài một ngày mỗi tháng"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following article.","passages":["<h3>Mehan Motors Appoints New CEO</h3><p>By Jonas Schulz</p><p>DETROIT (January 2)—This will be a year of firsts at Mehan Motors. For the first time in its 35-year history, the company is changing its top leadership; Mehan will soon welcome the first American and the first woman to hold the title of CEO. — <span class=\"pos\">[1]</span> —.</p><p>Dana Loeb will begin her tenure at Mehan Motors on February 1, the company announced yesterday. Ms. Loeb graduated with top honors from Clover University of Technology in Boston, where she completed a degree in electrical engineering. — <span class=\"pos\">[2]</span> —. She eventually rose to lead the electric vehicle (EV) division at Tafts Motors in Detroit. Within two years, the company promoted her to the position of chief operating officer.</p><p>Ms. Loeb eventually left her position at Tafts Motors to become CEO of the British car company Norana, where she spearheaded the introduction of its popular subcompact EV, the Radar. Within its category, this vehicle achieved a stunning 20% higher range on a single charge than its nearest EV competitor. — <span class=\"pos\">[3]</span> —.</p><p>Ms. Loeb summarized her vision for Mehan Motors in a recent interview. — <span class=\"pos\">[4]</span> —. “I look forward to leveraging the company’s abundant talent to build EVs that are affordable to a mass market. The vehicles must be offered at a price that is reasonable for the average consumer.”</p>"],"vi":"Mehan Motors bổ nhiệm CEO mới\nBởi Jonas Schulz\n\nDETROIT (ngày 2 tháng 1) — Đây sẽ là một năm của những cột mốc lần đầu tiên tại Mehan Motors. Lần đầu tiên trong lịch sử 35 năm, công ty sẽ thay đổi vị trí lãnh đạo cao nhất; Mehan sắp chào đón CEO người Mỹ đầu tiên và cũng là nữ CEO đầu tiên của mình. — [1] —\n\nDana Loeb sẽ bắt đầu nhiệm kỳ của bà tại Mehan Motors vào ngày 1 tháng 2, theo thông báo của công ty vào ngày hôm qua. Bà Loeb tốt nghiệp loại xuất sắc tại Đại học Công nghệ Clover ở Boston, nơi bà hoàn thành bằng kỹ sư điện. — [2] — Sau đó, bà dần thăng tiến để lãnh đạo bộ phận xe điện (EV) tại Tafts Motors ở Detroit. Chỉ trong vòng hai năm, công ty đã thăng chức bà lên vị trí giám đốc điều hành (COO).\n\nCuối cùng, bà Loeb rời Tafts Motors để trở thành CEO của hãng xe Anh quốc Norana, nơi bà đóng vai trò chủ chốt trong việc giới thiệu mẫu xe điện cỡ nhỏ rất được ưa chuộng, Radar. Trong cùng phân khúc, mẫu xe này đã đạt được quãng đường di chuyển cao hơn 20% chỉ với một lần sạc so với đối thủ xe điện gần nhất. — [3] —\n\nBà Loeb đã tóm tắt tầm nhìn của mình cho Mehan Motors trong một cuộc phỏng vấn gần đây. — [4] — “Tôi mong muốn tận dụng nguồn nhân lực tài năng dồi dào của công ty để phát triển các mẫu xe điện có giá cả phải chăng cho thị trường đại chúng. Những chiếc xe phải được bán với mức giá hợp lý đối với người tiêu dùng trung bình.”","qs":[{"n":164,"q":"What is the purpose of the article?","qvi":"Mục đích của bài báo là gì?","opts":["To describe the future of electric vehicles","To profile a company’s incoming leader","To analyze trends in the sales prices of automobiles","To explain how a company decision was made"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Tiêu đề \"Mehan Motors Appoints New CEO\" (Mehan Motors bổ nhiệm CEO mới) và cả bài giới thiệu học vấn, sự nghiệp, tầm nhìn của bà Dana Loeb → giới thiệu lãnh đạo sắp nhậm chức.\n(A) Mô tả tương lai của xe điện\n(B) Giới thiệu chân dung lãnh đạo sắp nhậm chức của một công ty\n(C) Phân tích xu hướng giá bán ô tô\n(D) Giải thích cách một quyết định của công ty được đưa ra"},{"n":165,"q":"Where was Ms. Loeb’s first experience working on electric vehicles?","qvi":"Trải nghiệm đầu tiên của bà Loeb khi làm việc với xe điện là ở đâu?","opts":["At Mehan Motors","At Clover University of Technology","At Norana","At Tafts Motors"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Sau khi tốt nghiệp, \"She eventually rose to lead the electric vehicle (EV) division at Tafts Motors in Detroit\" (bà thăng tiến lên lãnh đạo bộ phận xe điện tại Tafts Motors); sau đó mới sang Norana → nơi đầu tiên làm xe điện là Tafts Motors.\n(A) Tại Mehan Motors\n(B) Tại Đại học Công nghệ Clover\n(C) Tại Norana\n(D) Tại Tafts Motors"},{"n":166,"q":"What is special about the Radar?","qvi":"Điểm đặc biệt của mẫu xe Radar là gì?","opts":["Its large size","Its attractive body design","Its long battery life","Its low price"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"this vehicle achieved a stunning 20% higher range on a single charge than its nearest EV competitor\" (đi được xa hơn 20% chỉ với một lần sạc) → pin dùng lâu. (A) sai: \"subcompact\" = cỡ nhỏ.\n(A) Kích thước lớn\n(B) Thiết kế thân xe đẹp mắt\n(C) Thời lượng pin lâu\n(D) Giá rẻ"},{"n":167,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“She also earned a certificate in corporate management.”","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n“Bà cũng đã lấy được chứng chỉ về quản trị doanh nghiệp.”","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Câu chèn nói về học vấn (\"also earned a certificate\" – cũng lấy thêm chứng chỉ) → phải đặt ngay sau câu nói về bằng đại học: \"Ms. Loeb graduated with top honors from Clover University of Technology... where she completed a degree in electrical engineering.\" → vị trí [2]."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following advertisement.","passages":["<h4>Dan’s Specialty Bicycles</h4><p>60 Everett Way, London, SW11 1AH<br>Hours: Monday–Sunday 10 A.M.–6 P.M.</p><h3>Tenth Annual Sale of Secondhand Bicycles!</h3><p>We are known for our stock of high-end racing bicycles, but for a limited time every year, we offer a wide selection of secondhand mountain, road, and hybrid bicycles for all ages and abilities. Each bicycle has been refurbished by a certified technician to ensure a smooth, safe ride. Prices range from £15 to £50.</p><p>The sale runs from 9 May to 22 May. Show or mention this advertisement to receive ten percent off the price of any secondhand or new bicycle. For more information, visit www.dansspecialtybicycles.co.uk.</p>"],"vi":"Dan’s Specialty Bicycles\nĐịa chỉ: 60 Everett Way, London, SW11 1AH\nGiờ mở cửa: Thứ Hai – Chủ Nhật, 10:00 sáng – 6:00 chiều\n\nĐợt giảm giá xe đạp đã qua sử dụng thường niên lần thứ 10!\n\nChúng tôi nổi tiếng với các dòng xe đạp đua cao cấp, nhưng trong một khoảng thời gian giới hạn mỗi năm, chúng tôi cung cấp nhiều loại xe đạp đã qua sử dụng gồm xe đạp leo núi, xe đạp đường trường và xe đạp lai, phù hợp với mọi lứa tuổi và trình độ. Mỗi chiếc xe đạp đều đã được kỹ thuật viên được chứng nhận tân trang lại nhằm đảm bảo chuyến đi êm ái và an toàn. Giá bán dao động từ 15 đến 50 bảng Anh.\n\nĐợt giảm giá diễn ra từ ngày 9 tháng 5 đến ngày 22 tháng 5. Hãy xuất trình hoặc nhắc đến quảng cáo này để được giảm 10% giá của bất kỳ xe đạp đã qua sử dụng hoặc xe đạp mới nào. Để biết thêm thông tin, vui lòng truy cập www.dansspecialtybicycles.co.uk.","qs":[{"n":168,"q":"What is the main purpose of the advertisement?","qvi":"Mục đích chính của quảng cáo là gì?","opts":["To announce a store’s grand opening","To encourage bicyclists to compete in a race","To generate interest in an annual event","To invite people to attend a bicycle repair workshop"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Tiêu đề \"Tenth Annual Sale of Secondhand Bicycles!\" (Đợt giảm giá xe đạp cũ thường niên lần thứ 10) → quảng bá một sự kiện hằng năm.\n(A) Thông báo khai trương cửa hàng\n(B) Khuyến khích người đi xe đạp thi đấu\n(C) Thu hút sự quan tâm đến một sự kiện thường niên\n(D) Mời mọi người đến buổi workshop sửa xe đạp"},{"n":169,"q":"What is indicated about Dan’s Specialty Bicycles?","qvi":"Điều gì được cho biết về Dan’s Specialty Bicycles?","opts":["It will increase the price of most bicycles by ten percent next year.","It has several locations in London.","It is open seven days a week.","It will host a party in May."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"Hours: Monday–Sunday 10 A.M.–6 P.M.\" (Giờ mở cửa: Thứ Hai – Chủ Nhật) → mở cửa cả 7 ngày trong tuần.\n(A) Sẽ tăng giá hầu hết xe đạp thêm 10% vào năm sau\n(B) Có nhiều chi nhánh tại London\n(C) Mở cửa 7 ngày/tuần\n(D) Sẽ tổ chức một bữa tiệc vào tháng 5"},{"n":170,"q":"What is suggested about the secondhand bicycles?","qvi":"Điều gì được gợi ý về những chiếc xe đạp cũ?","opts":["They will be available for sale all year.","Each comes with a bicycle helmet.","Some are designed for children.","Some need to be repaired."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: \"...secondhand mountain, road, and hybrid bicycles for all ages and abilities\" (phù hợp với mọi lứa tuổi) → có xe cho trẻ em. (A) sai: \"for a limited time every year\"; (D) sai: \"Each bicycle has been refurbished\" (đã được tân trang).\n(A) Sẽ được bán quanh năm\n(B) Mỗi chiếc đều đi kèm mũ bảo hiểm\n(C) Một số chiếc dành cho trẻ em\n(D) Một số chiếc cần được sửa"},{"n":171,"q":"What information is NOT included in the advertisement?","qvi":"Thông tin nào KHÔNG có trong quảng cáo?","opts":["The type of bicycle regularly sold at Dan’s Specialty Bicycles","The credentials of those who serviced some bicycles","How to save money on a purchase at Dan’s Specialty Bicycles","Where to find bicycle trails in the London area"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: (A) có: \"We are known for our stock of high-end racing bicycles\"; (B) có: \"refurbished by a certified technician\"; (C) có: \"Show or mention this advertisement to receive ten percent off\". Không nhắc đến đường mòn xe đạp → (D).\n(A) Loại xe đạp được bán thường xuyên tại cửa hàng\n(B) Trình độ/chứng nhận của những người bảo dưỡng xe\n(C) Cách tiết kiệm tiền khi mua hàng tại cửa hàng\n(D) Nơi tìm đường mòn xe đạp quanh London"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Morton Talbert (7:32 P.M.)</b></p><p>Has anyone used the Internet device Bam Booster?</p></div><div class=\"msg\"><p><b>Chaya Leven (7:37 P.M.)</b></p><p>I have used other brands in the past, but now I have the Bam Booster 10, and I love it.</p></div><div class=\"msg\"><p><b>Laria Jones (7:38 P.M.)</b></p><p>I have a poor connection to the Internet in my basement. I have tried several Internet boosters, but they haven’t helped at all. They’re just not worth the money.</p></div><div class=\"msg\"><p><b>Morton Talbert (7:40 P.M.)</b></p><p>I am looking for a reliable booster that’s easy to set up.</p></div><div class=\"msg\"><p><b>Chaya Leven (7:41 P.M.)</b></p><p>That one is the best.</p></div><div class=\"msg\"><p><b>Leonard Keff (7:48 P.M.)</b></p><p>I have the Bam Booster 7. It works fine and was easy to set up, but I’ve heard their newer Bam Booster 10 model is better.</p></div><div class=\"msg\"><p><b>Danyelle Walken (7:52 P.M.)</b></p><p>I have the Zeertox Signal Booster and it’s somewhat big and unsightly. On the positive side, it’s inexpensive and it works.</p></div><div class=\"msg\"><p><b>Chaya Leven (7:58 P.M.)</b></p><p>The Bam Booster 10 is much smaller. It does cost more than other brands, though.</p></div><div class=\"msg\"><p><b>Morton Talbert (8:02 P.M.)</b></p><p>I didn’t realize there was more than one Bam Booster model. Thanks, everybody! Now I know what to get.</p></div>"],"vi":"Morton Talbert (7:32 tối): Có ai đã từng dùng thiết bị Internet Bam Booster chưa?\n\nChaya Leven (7:37 tối): Trước đây tôi đã dùng các thương hiệu khác, nhưng hiện tại tôi đang dùng Bam Booster 10, và tôi rất thích nó.\n\nLaria Jones (7:38 tối): Tôi có kết nối Internet rất kém ở tầng hầm. Tôi đã thử một số bộ tăng cường Internet rồi, nhưng chúng chẳng giúp ích gì cả. Chúng không đáng với số tiền bỏ ra.\n\nMorton Talbert (7:40 tối): Tôi đang tìm một bộ tăng cường đáng tin cậy và dễ cài đặt.\n\nChaya Leven (7:41 tối): Loại đó là tốt nhất.\n\nLeonard Keff (7:48 tối): Tôi đang dùng Bam Booster 7. Nó hoạt động ổn và dễ lắp đặt, nhưng tôi nghe nói mẫu Bam Booster 10 mới hơn thì tốt hơn.\n\nDanyelle Walken (7:52 tối): Tôi có Zeertox Signal Booster, nó khá to và trông không đẹp lắm. Tuy nhiên, điểm tích cực là nó rẻ và hoạt động hiệu quả.\n\nChaya Leven (7:58 tối): Bam Booster 10 nhỏ gọn hơn nhiều. Tuy nhiên, giá của nó cao hơn so với các thương hiệu khác.\n\nMorton Talbert (8:02 tối): Tôi không biết là có nhiều hơn một mẫu Bam Booster. Cảm ơn mọi người nhé! Giờ thì tôi đã biết nên mua loại nào rồi.","qs":[{"n":172,"q":"Why did Mr. Talbert initiate the online chat discussion?","qvi":"Vì sao ông Talbert bắt đầu cuộc trò chuyện trực tuyến?","opts":["To solicit advice about purchasing a product","To provide a review of an appliance","To offer a specialized tool for sale","To ask how to install equipment in a basement"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Ông hỏi \"Has anyone used the Internet device Bam Booster?\" và \"I am looking for a reliable booster\" (Tôi đang tìm một bộ tăng cường đáng tin cậy), cuối cùng nói \"Now I know what to get\" (Giờ tôi biết nên mua gì) → xin lời khuyên trước khi mua.\n(A) Để xin lời khuyên về việc mua một sản phẩm\n(B) Để đánh giá một thiết bị\n(C) Để rao bán một công cụ chuyên dụng\n(D) Để hỏi cách lắp đặt thiết bị trong tầng hầm"},{"n":173,"q":"Who reported a negative experience with multiple products?","qvi":"Ai phản ánh trải nghiệm không tốt với nhiều sản phẩm?","opts":["Mr. Talbert","Ms. Jones","Mr. Keff","Ms. Walken"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Laria Jones (7:38): \"I have tried several Internet boosters, but they haven’t helped at all. They’re just not worth the money.\" (Tôi đã thử vài bộ tăng cường nhưng chẳng giúp gì cả) → several = multiple products.\n(A) Ông Talbert\n(B) Bà Jones\n(C) Ông Keff\n(D) Bà Walken"},{"n":174,"q":"At 7:41 P.M., what does Ms. Leven imply when she writes, “That one is the best”?","qvi":"Lúc 7:41 tối, bà Leven ngụ ý gì khi viết “Loại đó là tốt nhất”?","opts":["She appreciated a prior online chat discussion.","She has been eager to try a new product.","She finds Mr. Talbert’s question helpful.","She is pleased with the device she uses."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Trước đó bà nói \"now I have the Bam Booster 10, and I love it\" (tôi đang dùng Bam Booster 10 và rất thích). Khi ông Talbert nói cần bộ đáng tin cậy, dễ cài đặt, bà đáp \"That one is the best\" → bà hài lòng với thiết bị mình đang dùng.\n(A) Bà trân trọng một cuộc trò chuyện trực tuyến trước đó.\n(B) Bà háo hức muốn thử sản phẩm mới.\n(C) Bà thấy câu hỏi của ông Talbert hữu ích.\n(D) Bà hài lòng với thiết bị mình đang dùng."},{"n":175,"q":"What is indicated about the Zeertox Signal Booster?","qvi":"Điều gì được cho biết về bộ tăng cường tín hiệu Zeertox?","opts":["It is too expensive.","It is unreliable.","It is better than the older version.","It is comparatively large."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Danyelle Walken (7:52): \"I have the Zeertox Signal Booster and it’s somewhat big and unsightly\" (khá to và không đẹp mắt); Chaya Leven nói thêm \"The Bam Booster 10 is much smaller\" → Zeertox to hơn so với loại khác. (A) sai: \"it’s inexpensive\"; (B) sai: \"it works\".\n(A) Nó quá đắt.\n(B) Nó không đáng tin cậy.\n(C) Nó tốt hơn phiên bản cũ.\n(D) Nó tương đối to."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mail and advertisement.","passages":["<div class=\"hdr\"><p><b>To:</b> Mark Schroeder</p><p><b>From:</b> Ashley Nguyen</p><p><b>Date:</b> May 5</p><p><b>Subject:</b> Seasonal hiring</p></div><p>Hi, Mark,</p><p>I hope you can take care of our summer hiring this year. Last year, Nancy Adams put an advertisement in the <i>Shoreline Observer</i>, and we had applicants right away. I suggest using that paper again. We should hire the same number of workers as last year, but this time, all four should be full-time. Please write a new advertisement, and we can look at it together next week before sending it out.</p><p>And by the way, thanks for your work getting the Gravel Road store ready to open. I know you will be a great store manager when it is operational next month. One of your first responsibilities will be to put together a terrific staff.</p><p>Best,</p><p>Ashley Nguyen, General Manager<br>Surf Bird Beachwear</p>","<h3>Surf Bird Beachwear is Hiring for the Summer!</h3><p>Surf Bird Beachwear, Jaxon Shore’s best shop for casual clothing and beach supplies, has openings for four full-time workers. These seasonal positions will be available from the beginning of June until the end of August. Duties include handling sales, stocking shelves, assisting customers, and setting up displays. Some early morning and weekend work is required. We offer a competitive salary and excellent working conditions.</p><p>Surf Bird Beachwear has two locations in Jaxon Shore: the original Pelican Inlet store and, opening in June, our new Gravel Road location. All interviews will be conducted at the Gravel Road store. Go to www.surfbirdbeachwear.com/jobs to apply.</p>"],"vi":"BÀI ĐỌC 1 – EMAIL\nNgười nhận: Mark Schroeder\nNgười gửi: Ashley Nguyen\nNgày: 5 tháng 5\nChủ đề: Tuyển dụng theo mùa\n\nChào Mark,\n\nTôi hy vọng anh có thể phụ trách việc tuyển dụng nhân viên mùa hè năm nay. Năm ngoái, Nancy Adams đã đăng một quảng cáo trên báo Shoreline Observer, và chúng ta đã có ứng viên ngay lập tức. Tôi đề nghị tiếp tục sử dụng tờ báo đó. Chúng ta nên tuyển cùng số lượng nhân viên như năm ngoái, nhưng lần này cả bốn người đều làm toàn thời gian. Vui lòng viết một quảng cáo mới, và tuần tới chúng ta sẽ cùng xem lại trước khi gửi đi.\n\nNhân tiện, cảm ơn anh vì công việc chuẩn bị để cửa hàng Gravel Road sẵn sàng khai trương. Tôi biết anh sẽ là một quản lý cửa hàng tuyệt vời khi cửa hàng đi vào hoạt động vào tháng tới. Một trong những trách nhiệm đầu tiên của anh sẽ là tập hợp một đội ngũ nhân viên thật tốt.\n\nTrân trọng,\nAshley Nguyen, Quản lý tổng\nSurf Bird Beachwear\n\nBÀI ĐỌC 2 – QUẢNG CÁO TUYỂN DỤNG\nSurf Bird Beachwear đang tuyển dụng cho mùa hè!\n\nSurf Bird Beachwear, cửa hàng thời trang thường ngày và đồ đi biển tốt nhất tại Jaxon Shore, đang tuyển bốn nhân viên toàn thời gian. Các vị trí làm việc theo mùa này sẽ kéo dài từ đầu tháng 6 đến hết tháng 8. Nhiệm vụ công việc bao gồm: xử lý bán hàng, sắp xếp hàng lên kệ, hỗ trợ khách hàng và thiết lập các khu trưng bày sản phẩm. Có thể phải làm việc sáng sớm và cuối tuần. Chúng tôi đưa ra mức lương cạnh tranh và điều kiện làm việc rất tốt.\n\nSurf Bird Beachwear có hai cửa hàng tại Jaxon Shore: cửa hàng Pelican Inlet (chi nhánh gốc) và cửa hàng Gravel Road mới, khai trương vào tháng 6. Tất cả các buổi phỏng vấn sẽ được tổ chức tại cửa hàng Gravel Road. Truy cập www.surfbirdbeachwear.com/jobs để ứng tuyển.","qs":[{"n":176,"q":"Why did Ms. Nguyen write the e-mail?","qvi":"Vì sao cô Nguyen viết e-mail?","opts":["To make a job offer to an applicant","To assign a task to an employee","To announce opening hours at a store","To ask a question about newspaper advertising"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: E-mail: “I hope you can take care of our summer hiring this year.” và “Please write a new advertisement…” → cô Nguyen giao việc tuyển dụng / viết quảng cáo cho Mark.\n(A) Để đưa ra lời mời làm việc cho một ứng viên\n(B) Để giao nhiệm vụ cho một nhân viên\n(C) Để thông báo giờ mở cửa của một cửa hàng\n(D) Để hỏi về việc quảng cáo trên báo"},{"n":177,"q":"What is suggested about the workers who were hired last year?","qvi":"Điều gì được gợi ý về những nhân viên được tuyển năm ngoái?","opts":["They will be rehired this year.","They will begin working in May.","They lived near Jaxon Shore.","They did not all work full-time."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: E-mail: “We should hire the same number of workers as last year, but this time, all four should be full-time.” → năm ngoái không phải cả bốn người đều làm toàn thời gian.\n(A) Họ sẽ được tuyển lại năm nay\n(B) Họ sẽ bắt đầu làm việc vào tháng 5\n(C) Họ sống gần Jaxon Shore\n(D) Không phải tất cả đều làm toàn thời gian"},{"n":178,"q":"What is NOT mentioned as a job duty in the advertisement?","qvi":"Điều nào KHÔNG được nêu là nhiệm vụ công việc trong quảng cáo?","opts":["Placing items on shelves","Displaying merchandise","Unloading deliveries","Helping shoppers"],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Quảng cáo: “Duties include handling sales, stocking shelves (A), assisting customers (D), and setting up displays (B).” → không nhắc đến việc dỡ hàng.\n(A) Sắp xếp hàng lên kệ\n(B) Trưng bày sản phẩm\n(C) Dỡ hàng được giao\n(D) Hỗ trợ khách mua hàng"},{"n":179,"q":"What is most likely true about the job interviews?","qvi":"Điều gì có khả năng đúng nhất về các buổi phỏng vấn?","opts":["They will take place in July.","They will be held at the Pelican Inlet location.","They will be led by Mr. Schroeder.","They will be conducted online."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Kết hợp 2 bài: E-mail – Mark sẽ là quản lý cửa hàng Gravel Road và “One of your first responsibilities will be to put together a terrific staff.”; Quảng cáo – “All interviews will be conducted at the Gravel Road store.” → ông Schroeder sẽ chủ trì phỏng vấn.\n(A) Sẽ diễn ra vào tháng 7\n(B) Sẽ được tổ chức tại cửa hàng Pelican Inlet\n(C) Sẽ do ông Schroeder chủ trì\n(D) Sẽ được tổ chức trực tuyến"},{"n":180,"q":"In the advertisement, the word “original” in paragraph 2, line 1, is closest in meaning to","qvi":"Trong quảng cáo, từ “original” ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["first","unique","imaginative","best"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: “the original Pelican Inlet store” → “original” = cửa hàng đầu tiên / ban đầu (so với cửa hàng Gravel Road mới), không phải “độc đáo” hay “tốt nhất”.\n(A) đầu tiên\n(B) độc đáo\n(C) sáng tạo\n(D) tốt nhất"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following e-mail and blog post.","passages":["<div class=\"hdr\"><p><b>To:</b> Executive Team</p><p><b>From:</b> Kota Adachi</p><p><b>Date:</b> October 11</p><p><b>Subject:</b> Trak-4 jets</p></div><p>Dear Team:</p><p>In late December, we will take possession of the first six of the twelve Trak-4 jets we ordered last year. The remaining jets will be delivered throughout the coming year. I believe these narrow-body jets represent the future of our airline. In addition to being the quietest jets on the market today, they are 20 percent more fuel efficient than the DB90s that we currently fly. They also have a smaller passenger capacity of 76 seats, making them ideally suited to underserved regional markets.</p><p>In anticipation of the upcoming delivery, we must decide what routes to fly the new aircraft on. Perhaps we need to rethink our entire hub system. We currently have seven regional urban hubs where our flights connect. Passengers flying between smaller cities must change planes at one of these hubs. Landing fees at these larger airports tend to be very high. We could drastically reduce our operating expenses by flying narrow-body craft directly to and from airports located away from these major urban centers.</p><p>I am setting up a meeting one week from today to discuss this issue. We will analyze the profitability of each of our current routes in order to reach an informed decision.</p><p>Kota Adachi<br>CEO, Ventana Airlines</p>","<h3>Travelaider: A Blog about Where, Why, and How to Travel</h3><p>By Ken Ogawa</p><p>Springfield (January 20)—I recently flew nonstop from Silver City to Centerville on Ventana Airlines. That’s right, I said \"nonstop.\" Ventana now offers direct flights between these two small cities with no need for travelers to change planes at Midwest National Airport, our only regional hub. I surely will not miss hurrying between terminals at Midwest through a sea of fellow passengers.</p><p>As for the flight itself, Ventana’s new jets are a vast improvement over the old ones. The possibility of being stuck in the middle seat is no longer a concern. The new aircraft have only two seats on each side of the aisle, so everyone gets an aisle or window seat. The seats are also more comfortable than most airplane seats. The legroom was a little tight for a person my size, but someone of average height should have plenty of room to stretch out.</p>"],"vi":"EMAIL TỪ CEO – KOTA ADACHI\nGửi đến: Ban điều hành\nTừ: Kota Adachi\nNgày: 11 tháng 10\nChủ đề: Máy bay Trak-4\n\nKính gửi Ban điều hành,\n\nVào cuối tháng 12, chúng ta sẽ tiếp nhận sáu chiếc đầu tiên trong số mười hai chiếc máy bay Trak-4 mà chúng ta đã đặt hàng vào năm ngoái. Sáu chiếc còn lại sẽ được bàn giao trong suốt năm tới. Tôi tin rằng dòng máy bay thân hẹp Trak-4 này sẽ là tương lai của hãng hàng không của chúng ta. Ngoài việc là những chiếc máy bay yên tĩnh nhất trên thị trường hiện nay, chúng còn tiết kiệm nhiên liệu hơn 20% so với dòng DB90 mà chúng ta đang sử dụng. Chúng cũng có sức chứa hành khách nhỏ hơn – chỉ 76 ghế, khiến chúng đặc biệt phù hợp với các thị trường khu vực chưa được phục vụ đầy đủ.\n\nĐể chuẩn bị cho đợt bàn giao sắp tới, chúng ta cần quyết định tuyến bay nào sẽ được sử dụng cho máy bay mới này. Có lẽ chúng ta cần xem xét lại toàn bộ hệ thống các điểm trung chuyển hiện nay. Chúng ta hiện có bảy điểm trung chuyển đô thị khu vực – nơi các chuyến bay kết nối với nhau. Hành khách di chuyển giữa các thành phố nhỏ phải chuyển máy bay ở một trong các điểm trung chuyển này. Phí hạ cánh tại những sân bay lớn này thường rất cao. Chúng ta có thể giảm đáng kể chi phí vận hành bằng cách cho máy bay thân hẹp bay thẳng đến/đi từ các sân bay nằm cách xa các trung tâm đô thị lớn này.\n\nTôi sẽ tổ chức một cuộc họp vào một tuần sau kể từ hôm nay để thảo luận về vấn đề này. Chúng ta sẽ phân tích lợi nhuận của từng tuyến bay hiện tại để đưa ra quyết định sáng suốt.\n\nKota Adachi\nCEO, Ventana Airlines\n\nBLOG CỦA KEN OGAWA\nTravelaider: Blog về Nơi, Lý do và Cách du lịch\nTác giả: Ken Ogawa\n\nSpringfield (ngày 20 tháng 1) — Tôi mới đây đã bay thẳng không dừng từ Silver City đến Centerville trên chuyến bay của Ventana Airlines. Đúng vậy, là “không dừng.” Ventana hiện cung cấp các chuyến bay trực tiếp giữa hai thành phố nhỏ này, hành khách không cần phải chuyển máy bay tại sân bay Midwest National Airport – điểm trung chuyển khu vực duy nhất của chúng tôi. Tôi chắc chắn sẽ không nhớ cảm giác phải vội vã băng qua các nhà ga tại Midwest giữa một biển người.\n\nVề trải nghiệm bay, máy bay mới của Ventana là một sự cải tiến đáng kể so với dòng cũ. Không còn lo bị kẹt ở ghế giữa nữa. Máy bay mới chỉ có hai ghế ở mỗi bên lối đi, nên mọi người đều được ngồi ghế sát lối đi hoặc sát cửa sổ. Các ghế này cũng thoải mái hơn hầu hết ghế máy bay khác. Khoảng để chân hơi chật với người cỡ như tôi, nhưng với người có chiều cao trung bình thì sẽ có đủ chỗ để duỗi chân thoải mái.","qs":[{"n":181,"q":"According to the e-mail, what will happen over the next twelve months?","qvi":"Theo e-mail, điều gì sẽ diễn ra trong 12 tháng tới?","opts":["Travel to smaller cities will decrease.","Landing fees at airports will increase.","Ventana Airlines will receive new aircraft.","Ventana Airlines will hire 76 additional staff."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: E-mail: “In late December, we will take possession of the first six of the twelve Trak-4 jets… The remaining jets will be delivered throughout the coming year.”\n(A) Việc đi lại đến các thành phố nhỏ sẽ giảm\n(B) Phí hạ cánh tại sân bay sẽ tăng\n(C) Ventana Airlines sẽ nhận máy bay mới\n(D) Ventana Airlines sẽ tuyển thêm 76 nhân viên"},{"n":182,"q":"How does the Trak-4 jet compare with the DB90 aircraft?","qvi":"Máy bay Trak-4 so với máy bay DB90 như thế nào?","opts":["It has more legroom.","It has larger windows.","It can accommodate more passengers per flight.","It has no middle seats in its cabin."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp 2 bài: E-mail – Trak-4 là máy bay mới thay cho DB90 đang dùng; Blog – “Ventana’s new jets are a vast improvement over the old ones… The new aircraft have only two seats on each side of the aisle, so everyone gets an aisle or window seat.” → không có ghế giữa. (C) sai vì Trak-4 có sức chứa nhỏ hơn.\n(A) Có nhiều chỗ để chân hơn\n(B) Có cửa sổ lớn hơn\n(C) Chở được nhiều hành khách hơn mỗi chuyến\n(D) Không có ghế giữa trong khoang"},{"n":183,"q":"What can be concluded about the Ventana Airlines executive team?","qvi":"Có thể kết luận gì về ban lãnh đạo của Ventana Airlines?","opts":["It is no longer interested in using the Trak-4 jet.","Its next meeting will be held on January 20.","It decided to add routes that bypass urban hubs.","It received an award for achieving its profitability goals."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: E-mail: “We could drastically reduce our operating expenses by flying narrow-body craft directly to and from airports located away from these major urban centers.”; Blog: Ventana nay có chuyến bay thẳng giữa hai thành phố nhỏ, không cần đổi máy bay ở điểm trung chuyển → ban lãnh đạo đã quyết định mở tuyến bỏ qua các hub đô thị.\n(A) Không còn hứng thú sử dụng máy bay Trak-4\n(B) Cuộc họp tiếp theo sẽ diễn ra ngày 20/1\n(C) Đã quyết định thêm các tuyến bay bỏ qua các điểm trung chuyển đô thị\n(D) Nhận giải thưởng vì đạt mục tiêu lợi nhuận"},{"n":184,"q":"What does Mr. Ogawa dislike about connecting at a hub?","qvi":"Ông Ogawa không thích điều gì khi phải nối chuyến tại điểm trung chuyển?","opts":["Waiting in line at security checkpoints","Rushing from one terminal to another","Having to eat quickly at the airport","Boarding and deboarding the aircraft"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Blog: “I surely will not miss hurrying between terminals at Midwest through a sea of fellow passengers.”\n(A) Xếp hàng ở điểm kiểm tra an ninh\n(B) Vội vã từ nhà ga này sang nhà ga khác\n(C) Phải ăn vội ở sân bay\n(D) Lên và xuống máy bay"},{"n":185,"q":"What is most likely true about Mr. Ogawa?","qvi":"Điều nào có khả năng đúng nhất về ông Ogawa?","opts":["He is relatively tall.","He is a commercial pilot.","He lives in Centerville.","He prefers a window seat."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Blog: “The legroom was a little tight for a person my size, but someone of average height should have plenty of room to stretch out.” → ông cao hơn mức trung bình.\n(A) Ông khá cao\n(B) Ông là phi công thương mại\n(C) Ông sống ở Centerville\n(D) Ông thích ngồi ghế cạnh cửa sổ"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following notice, e-mail, and schedule.","passages":["<h3><b>Attention:</b> Oxton Science Museum Visitors</h3><p>The Gartner Wing of the museum is currently closed. We apologize for the inconvenience.</p><p>Please be patient as we prepare the space for our next exhibit, <i>The Power of Light</i>. Designed by curator Sachiko Morishita, it explores innovations that will affect the future, particularly in the world of lasers and optics. The exhibit will be open to members and private group tours starting August 15 and to the general public starting September 2.</p>","<div class=\"hdr\"><p><b>To:</b> Summer Interns &lt;interns@renmarksolutions.com&gt;</p><p><b>From:</b> Tae-Ho Mun &lt;thmun@renmarksolutions.com&gt;</p><p><b>Date:</b> July 7</p><p><b>Subject:</b> August trip</p></div><p>Good morning, team,</p><p>Interns and their mentors are invited to take a trip to the Oxton Science Museum on Friday, August 19. Many of you have been on previous Renmark Solutions trips, so you know they are always educational and exciting. Participants will get a look at the science and technology that drives our company and customers.</p><p>We will see <i>The Power of Light</i> exhibit as part of our group tour. Vouchers will be handed out for lunch at the museum’s restaurant.</p><p>Our schedule is as follows.</p><table><tr><td>9:00 A.M.</td><td>Meet in the company lobby (The bus departs at 9:15 A.M.)</td></tr><tr><td>10:00 A.M. to noon</td><td>Private group tour</td></tr><tr><td>Noon to 1:00 P.M.</td><td>Lunch in the museum restaurant</td></tr><tr><td>1:45 to 2:00 P.M.</td><td>Meet in room 203</td></tr><tr><td>3:15 P.M.</td><td>Bus leaves for the return to Renmark Solutions offices</td></tr></table><p>Yours,</p><p>Tae-Ho Mun<br>Research and Development Manager</p>","<h3>Oxton Science Museum</h3><h4>Viewing Room Schedule (Room 203)—August 19</h4><table><tr><th>Time</th><th>Event Title</th><th>Event Description</th></tr><tr><td>9:45 A.M.</td><td>“Optical Systems and Applied Observation”</td><td>Lecture by Professor Kaori Okada of Oxton University</td></tr><tr><td>10:30 A.M.</td><td>“Quantum Optics”</td><td>Presentation by Oxton Science Museum curator Wallace McCabe</td></tr><tr><td>1:00 P.M.</td><td>“Increasing the Use of Lasers”</td><td>Presentation by Jee-Min Hahm of Solfis University</td></tr><tr><td>1:45 P.M.</td><td><i>Mirrors, Lenses, and Prisms</i></td><td>Short film by FK Institute of Technology</td></tr><tr><td>2:45 P.M.</td><td>“New Platforms, New Products”</td><td>Product demonstrations by Bigham Industries</td></tr></table>"],"vi":"THÔNG BÁO TẠI BẢO TÀNG\nLưu ý: Gửi khách tham quan Bảo tàng Khoa học Oxton\n\nKhu vực Gartner Wing của bảo tàng hiện đang đóng cửa. Chúng tôi xin lỗi vì sự bất tiện này.\n\nMong quý khách kiên nhẫn trong khi chúng tôi chuẩn bị không gian cho triển lãm tiếp theo mang tên “The Power of Light”. Triển lãm do giám tuyển Sachiko Morishita thiết kế, khám phá các đổi mới sẽ ảnh hưởng đến tương lai, đặc biệt là trong lĩnh vực laser và quang học. Triển lãm sẽ mở cửa cho thành viên và các nhóm tham quan riêng từ ngày 15/8, và mở cửa cho công chúng từ ngày 2/9.\n\nEMAIL – THƯ MỜI THỰC TẬP SINH\nGửi: Nhóm thực tập sinh mùa hè\nTừ: Tae-Ho Mun\nNgày: 7 tháng 7\nChủ đề: Chuyến đi tháng 8\n\nChào buổi sáng cả nhóm,\n\nCác thực tập sinh và người hướng dẫn được mời tham gia chuyến tham quan Bảo tàng Khoa học Oxton vào Thứ Sáu, ngày 19 tháng 8. Nhiều bạn đã từng tham gia các chuyến đi của Renmark Solutions trước đây, nên chắc các bạn cũng biết rằng những chuyến đi này luôn bổ ích và thú vị. Người tham gia sẽ được tìm hiểu về khoa học và công nghệ đang thúc đẩy công ty và khách hàng của chúng ta.\n\nChúng ta sẽ xem triển lãm “The Power of Light” trong chuyến tham quan theo nhóm này. Phiếu ăn trưa sẽ được phát để dùng tại nhà hàng của bảo tàng.\n\nLịch trình như sau:\n9:00 sáng: Tập trung tại sảnh công ty (xe buýt khởi hành lúc 9:15 sáng)\n10:00 sáng – 12:00 trưa: Tham quan theo nhóm riêng\n12:00 – 1:00 chiều: Ăn trưa tại nhà hàng bảo tàng\n1:45 – 2:00 chiều: Tập trung tại phòng 203\n3:15 chiều: Xe buýt khởi hành về lại văn phòng Renmark Solutions\n\nThân,\nTae-Ho Mun\nQuản lý Nghiên cứu và Phát triển\n\nLỊCH PHÒNG CHIẾU (PHÒNG 203) – BẢO TÀNG KHOA HỌC OXTON – NGÀY 19/8\nGiờ | Tên sự kiện | Nội dung\n9:45 sáng | “Hệ thống quang học và quan sát ứng dụng” | Bài giảng của Giáo sư Kaori Okada – Đại học Oxton\n10:30 sáng | “Quang học lượng tử” | Bài trình bày của giám tuyển bảo tàng Wallace McCabe\n1:00 chiều | “Tăng cường ứng dụng laser” | Bài trình bày của Jee-Min Hahm – Đại học Solfis\n1:45 chiều | “Gương, thấu kính và lăng kính” | Phim ngắn của Viện Công nghệ FK\n2:45 chiều | “Nền tảng mới, sản phẩm mới” | Trình diễn sản phẩm của công ty Bigham Industries","qs":[{"n":186,"q":"What is one purpose of the notice?","qvi":"Một mục đích của thông báo là gì?","opts":["To direct people to a different entrance","To warn visitors about a temporary closure","To announce the grand opening of an institution","To explain a change in operating hours"],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Thông báo: “The Gartner Wing of the museum is currently closed. We apologize for the inconvenience.” – đóng cửa để chuẩn bị triển lãm tiếp theo (tạm thời).\n(A) Hướng mọi người đến lối vào khác\n(B) Báo cho khách về việc đóng cửa tạm thời\n(C) Thông báo lễ khai trương của một cơ sở\n(D) Giải thích thay đổi giờ hoạt động"},{"n":187,"q":"What is indicated about some of Renmark Solutions’ interns?","qvi":"Điều gì được nêu về một số thực tập sinh của Renmark Solutions?","opts":["They have volunteered at the Oxton Science Museum before.","They installed some audiovisual equipment for Mr. Mun.","They have joined Renmark Solutions trips in the past.","They assisted with the setup of an educational display."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: E-mail: “Many of you have been on previous Renmark Solutions trips…”\n(A) Họ từng làm tình nguyện viên tại Bảo tàng Khoa học Oxton\n(B) Họ đã lắp đặt thiết bị nghe nhìn cho ông Mun\n(C) Họ từng tham gia các chuyến đi của Renmark Solutions\n(D) Họ hỗ trợ dựng một khu trưng bày giáo dục"},{"n":188,"q":"What is suggested about the trip on August 19?","qvi":"Điều gì được gợi ý về chuyến đi ngày 19 tháng 8?","opts":["It will be led by Mr. Mun.","Its participants will travel by train.","It includes a tour of Ms. Morishita’s exhibit.","It must be paid for in advance by attendees."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Kết hợp: E-mail – “We will see The Power of Light exhibit as part of our group tour.”; Thông báo – triển lãm The Power of Light do giám tuyển Sachiko Morishita thiết kế. (B) sai vì đi bằng xe buýt.\n(A) Ông Mun sẽ dẫn đoàn\n(B) Người tham gia sẽ đi bằng tàu hỏa\n(C) Bao gồm tham quan triển lãm của bà Morishita\n(D) Người tham gia phải trả tiền trước"},{"n":189,"q":"Why will the interns go to room 203?","qvi":"Tại sao các thực tập sinh sẽ đến phòng 203?","opts":["To attend a lecture by Ms. Okada","To see a presentation by Mr. McCabe","To view a presentation by Solfis University","To watch a film by FK Institute of Technology"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp: E-mail – “1:45 to 2:00 P.M. Meet in room 203”; Lịch phòng 203 – 1:45 P.M.: Mirrors, Lenses, and Prisms – “Short film by FK Institute of Technology”.\n(A) Để nghe bài giảng của bà Okada\n(B) Để xem bài trình bày của ông McCabe\n(C) Để xem bài trình bày của Đại học Solfis\n(D) Để xem phim của Viện Công nghệ FK"},{"n":190,"q":"According to the schedule, when will a company give a presentation about its merchandise?","qvi":"Theo lịch trình, khi nào một công ty sẽ trình bày về sản phẩm của họ?","opts":["At 9:45 A.M.","At 10:30 A.M.","At 1:00 P.M.","At 2:45 P.M."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Lịch: 2:45 P.M. – “New Platforms, New Products” – “Product demonstrations by Bigham Industries” (merchandise = products).\n(A) Lúc 9:45 sáng\n(B) Lúc 10:30 sáng\n(C) Lúc 1:00 chiều\n(D) Lúc 2:45 chiều"}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following advertisement, price list, and review.","passages":["<h3>Protecto Umbrella Wrapping Machines</h3><p>Visitors entering and walking through a building with wet umbrellas unintentionally create wet and slippery floors. The Protecto Umbrella Wrapping machine (PUW machine) provides a simple and convenient way to address this problem. The machine is best placed in the entryway of your building. Upon entry, visitors insert their wet umbrellas into the machine. It automatically wraps the umbrella in a clear plastic bag, after which visitors can take their umbrellas. Upon leaving, they can discard the used bags in any nearby trash can.</p><p>PUW machines are available with one or two umbrella-wrapping devices and come in stainless steel or black. The machine wraps umbrellas in 1.5 seconds. The stand is mobile and thus can be rolled around to different locations. Purchase a PUW machine throughout November and receive a lightweight umbrella featuring our company logo.</p>","<h3>Protecto Products Price List</h3><table><tr><th>Product Number</th><th>Description</th><th>Price per Unit</th></tr><tr><td>143</td><td>PUW machine with two umbrella-wrapping devices. Price includes 2,000 bags. Perfect for large, high-foot-traffic areas. Available in stainless steel or black.</td><td>$450</td></tr><tr><td>144</td><td>PUW machine with one umbrella-wrapping device. Price includes 1,000 bags. Available in stainless steel or black.</td><td>$350</td></tr><tr><td>192</td><td>Box of 3,000 plastic bags for refilling any of our units. Available online only.</td><td>$100</td></tr><tr><td>194</td><td>Box of 1,000 plastic bags for refilling any of our units. Available online only.</td><td>$35</td></tr></table>","<p>https://www.setterlyproductreviews.com/officeequipment</p><h3>Office Equipment Review: Protecto Umbrella Wrapping Machines</h3><p>I love our new PUW machine! As the facilities manager of a medium-sized office building, I often have to deal with the inconvenience of wet floors caused by visitors entering with umbrellas. We used to have a large umbrella stand in the lobby where visitors could leave umbrellas, but only a few people used it. Then we tried an umbrella stand that included disposable plastic bags that visitors could tear off and put their umbrellas in. However, this method was ineffective because the bags were rather flimsy, thus failing to prevent water leakage.</p><p>So, in November, we decided to try a PUW machine. Because we have many visitors, we purchased the PUW machine with two devices and ordered it in stainless steel to match our modern-looking lobby.</p><p>Since then, the entranceway has been safer and cleaner. Visitors love that it is automatic, and everyone is grateful that the lobby is no longer wet and slippery because of umbrellas dripping with water!</p><p>—Andrew Barr</p>"],"vi":"ĐOẠN 1: QUẢNG CÁO\nMáy bọc ô Protecto\n\nKhách đi vào và đi lại trong tòa nhà với ô bị ướt vô tình làm sàn nhà ướt và trơn trượt. Máy bọc ô Protecto (gọi tắt là máy PUW) cung cấp một cách đơn giản và tiện lợi để giải quyết vấn đề này. Máy nên được đặt ở lối vào của tòa nhà. Khi đến, khách cho ô ướt của họ vào máy. Máy sẽ tự động bọc ô bằng túi nhựa trong suốt, sau đó khách có thể lấy ô đi. Khi rời đi, họ có thể vứt túi đã dùng vào bất kỳ thùng rác nào gần đó.\n\nMáy PUW có loại một hoặc hai thiết bị bọc ô và có màu thép không gỉ hoặc đen. Máy bọc ô trong 1,5 giây. Chân máy có thể di chuyển nên có thể được đẩy (lăn) đến các vị trí khác nhau. Mua máy PUW trong suốt tháng 11 sẽ được tặng kèm một chiếc ô nhẹ có in logo công ty.\n\nĐOẠN 2: BẢNG GIÁ SẢN PHẨM PROTECTO\nMã sản phẩm | Mô tả | Đơn giá\n143 | Máy PUW có 2 thiết bị bọc ô. Giá bao gồm 2.000 túi. Phù hợp cho khu vực rộng, đông người qua lại. Có màu thép không gỉ hoặc đen. | $450\n144 | Máy PUW có 1 thiết bị bọc ô. Giá bao gồm 1.000 túi. Có màu thép không gỉ hoặc đen. | $350\n192 | Hộp 3.000 túi nhựa để thay thế cho bất kỳ máy nào của chúng tôi. Chỉ bán online. | $100\n194 | Hộp 1.000 túi nhựa để thay thế cho bất kỳ máy nào của chúng tôi. Chỉ bán online. | $35\n\nĐOẠN 3: ĐÁNH GIÁ CỦA KHÁCH HÀNG\nhttps://www.setterlyproductreviews.com/officeequipment\nĐánh giá thiết bị văn phòng: Máy bọc ô Protecto\n\nTôi rất thích máy PUW mới của chúng tôi! Là người quản lý cơ sở vật chất của một tòa nhà văn phòng cỡ vừa, tôi thường phải đối mặt với sự bất tiện do sàn nhà ướt vì khách mang ô vào. Trước đây chúng tôi có đặt một giá để ô lớn ở sảnh để khách để ô, nhưng chỉ có vài người dùng. Sau đó, chúng tôi thử loại giá để ô có kèm túi nhựa dùng một lần để khách xé ra và cho ô vào, nhưng cách này không hiệu quả vì túi khá mỏng, không ngăn được nước rò rỉ.\n\nVì vậy, vào tháng 11, chúng tôi quyết định thử máy PUW. Vì có nhiều khách, chúng tôi đã mua máy PUW có hai thiết bị và đặt loại bằng thép không gỉ để phù hợp với sảnh mang phong cách hiện đại.\n\nTừ đó đến nay, khu vực lối vào đã an toàn và sạch sẽ hơn. Khách thích tính năng tự động, và ai cũng vui vì sảnh không còn ướt và trơn trượt do ô nhỏ nước nữa!\n\n—Andrew Barr","qs":[{"n":191,"q":"What does the advertisement suggest about PUW machines?","qvi":"Quảng cáo gợi ý điều gì về máy PUW?","opts":["Their material makes them cost-efficient.","They can wrap an umbrella in less than one second.","Their wheels allow them to be moved around.","They contain a receptacle for used bags."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: Quảng cáo: “The stand is mobile and thus can be rolled around to different locations.” (rolled around → có bánh xe). (B) sai vì máy bọc trong 1.5 giây; (D) sai vì khách vứt túi vào thùng rác gần đó.\n(A) Chất liệu giúp chúng tiết kiệm chi phí\n(B) Có thể bọc ô trong chưa đầy một giây\n(C) Bánh xe giúp chúng di chuyển được\n(D) Có ngăn chứa túi đã sử dụng"},{"n":192,"q":"What does the price list indicate about bags?","qvi":"Bảng giá cho biết điều gì về các túi?","opts":["They are available to buy in different quantities.","They fit in all brands of umbrella-wrapping machines.","They are not included in the price of PUW machines.","They are sold in retail stores."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Bảng giá: mã 192 – “Box of 3,000 plastic bags” và mã 194 – “Box of 1,000 plastic bags” → có hộp 3.000 và 1.000 túi. (B) sai: chỉ dùng cho máy của Protecto (“any of our units”); (C) sai: giá máy đã gồm túi; (D) sai: “Available online only”.\n(A) Có thể mua với số lượng khác nhau\n(B) Vừa với mọi nhãn hiệu máy bọc ô\n(C) Không bao gồm trong giá máy PUW\n(D) Được bán tại cửa hàng bán lẻ"},{"n":193,"q":"What is suggested about Mr. Barr?","qvi":"Điều gì được gợi ý về ông Barr?","opts":["He is a longtime customer of Protecto.","He received an umbrella with his order.","He works in a quiet office building.","He recently changed jobs."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Kết hợp: Quảng cáo – “Purchase a PUW machine throughout November and receive a lightweight umbrella…”; Đánh giá – “So, in November, we decided to try a PUW machine.” → ông Barr được tặng ô.\n(A) Ông là khách hàng lâu năm của Protecto\n(B) Ông nhận được một chiếc ô kèm theo đơn hàng\n(C) Ông làm việc trong một tòa nhà văn phòng yên tĩnh\n(D) Ông vừa mới đổi việc"},{"n":194,"q":"What is the cost of the product that Mr. Barr reviewed?","qvi":"Sản phẩm mà ông Barr đánh giá có giá bao nhiêu?","opts":["$35","$100","$350","$450"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp: Đánh giá – “we purchased the PUW machine with two devices”; Bảng giá – mã 143: máy PUW có hai thiết bị bọc ô – $450.\n(A) 35 đô\n(B) 100 đô\n(C) 350 đô\n(D) 450 đô"},{"n":195,"q":"What problem does Mr. Barr describe?","qvi":"Ông Barr mô tả vấn đề gì?","opts":["Protecto products are not modern-looking.","Visitors were not using an umbrella stand.","The lobby of his building is not clean.","Some disposable umbrella bags were too small."],"ans":"B","xp":"Đáp án: (B)\nCăn cứ: Đánh giá: “We used to have a large umbrella stand in the lobby where visitors could leave umbrellas, but only a few people used it.” (D) sai: túi mỏng (flimsy), không phải quá nhỏ.\n(A) Sản phẩm Protecto trông không hiện đại\n(B) Khách không sử dụng giá để ô\n(C) Sảnh tòa nhà của ông không sạch sẽ\n(D) Một số túi đựng ô dùng một lần quá nhỏ"}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following Web page and e-mails.","passages":["<p>https://www.croydonconstruction.co.nz/news</p><p><b>Home</b> | <b>News</b> | <b>Jobs</b> | <b>Contact Us</b></p><p>In December, Croydon Construction will mark 25 years in business on the South Island of New Zealand. We take great pride in the many buildings we have built here in Christchurch, where our headquarters are located, and in other locations along the South Island’s east coast.</p><p>We have been busy recently with some exciting projects. In Christchurch, we are building the Willoughby Medical Clinic on Grove Road, with a grand opening date of 1 November, and we are expanding the Blakefield Community Centre on Springdale Avenue. In Ashburton, we have nearly finished a 107-unit apartment complex on Passerine Way and have just broken ground on the new wing of the Dismus School on Sixth Street. Steve Kogler is our new chief site engineer.</p><p>Are you interested in employment with Croydon Construction? We’re hiring for both office and jobsite positions. Go to our Jobs page to view open positions and to apply.</p>","<div class=\"hdr\"><p><b>To:</b> Sanaa Rahija &lt;srahija@wilmawindows.co.nz&gt;</p><p><b>From:</b> Zack Makoare &lt;zmakoare@croydonconstruction.co.nz&gt;</p><p><b>Date:</b> 15 August</p><p><b>Subject:</b> Shipment overdue</p></div><p>Dear Ms. Rahija:</p><p>I am writing to check on the status of order 47992, which should have arrived here by 31 July and is now two weeks overdue. We are extremely concerned. The building’s completion date cannot be postponed. Please let me know when we can expect our windows to arrive. We shall withhold the balance of payment until the items have been received. Wilma Windows has been our supplier for many years, and this is the first time a problem like this has occurred.</p><p>Thank you for your prompt attention to this matter.</p><p>Sincerely,</p><p>Zack Makoare<br>Construction Manager, Croydon Construction</p>","<div class=\"hdr\"><p><b>To:</b> Zack Makoare &lt;zmakoare@croydonconstruction.co.nz&gt;</p><p><b>From:</b> Sanaa Rahija &lt;srahija@wilmawindows.co.nz&gt;</p><p><b>Date:</b> 16 August</p><p><b>Subject:</b> RE: Shipment overdue</p></div><p>Dear Mr. Makoare:</p><p>Please accept my apologies for the lateness of order 47992. A machine in our factory malfunctioned, creating flaws in the window glass. The machine has been repaired, and the factory is back to its usual production schedule. We are expediting your order and will ship it tomorrow. It will arrive at your medical clinic construction site on 20 August. As a goodwill gesture, we will refund your entire shipping fee.</p><p>Sincerely,</p><p>Sanaa Rahija</p>"],"vi":"ĐOẠN VĂN TRÊN TRANG WEB\nhttps://www.croydonconstruction.co.nz/news\nTrang chủ | Tin tức | Việc làm | Liên hệ\n\nVào tháng 12, Croydon Construction sẽ kỷ niệm 25 năm hoạt động tại Đảo Nam của New Zealand. Chúng tôi rất tự hào về nhiều tòa nhà mà mình đã xây dựng tại Christchurch – nơi đặt trụ sở chính – và ở nhiều địa điểm khác dọc theo bờ đông của Đảo Nam.\n\nGần đây chúng tôi rất bận rộn với một số dự án thú vị. Tại Christchurch, chúng tôi đang xây dựng Phòng khám Willoughby Medical Clinic trên đường Grove Road, dự kiến khai trương ngày 1 tháng 11, và đang mở rộng Trung tâm cộng đồng Blakefield trên đại lộ Springdale Avenue. Tại Ashburton, chúng tôi gần hoàn thành khu căn hộ 107 căn trên đường Passerine Way và vừa khởi công khu nhà mới của trường Dismus trên đường Sixth Street. Steve Kogler là kỹ sư trưởng công trường mới của chúng tôi.\n\nBạn có quan tâm đến việc làm tại Croydon Construction không? Chúng tôi đang tuyển cả vị trí văn phòng và công trường. Hãy vào trang Jobs (Việc làm) để xem các vị trí đang tuyển và nộp hồ sơ.\n\nEMAIL 1\nGửi: Sanaa Rahija\nTừ: Zack Makoare\nNgày: 15 tháng 8\nChủ đề: Lô hàng quá hạn\n\nKính gửi bà Rahija,\n\nTôi viết thư để kiểm tra tình trạng của đơn hàng 47992, lẽ ra đã phải đến nơi trước ngày 31/7, nhưng nay đã trễ hai tuần. Chúng tôi vô cùng lo lắng. Ngày hoàn thành tòa nhà không thể dời lại. Vui lòng cho tôi biết khi nào chúng tôi có thể nhận được cửa sổ. Chúng tôi sẽ giữ lại phần thanh toán còn lại cho đến khi nhận được hàng. Wilma Windows là nhà cung cấp của chúng tôi trong nhiều năm, và đây là lần đầu tiên xảy ra sự cố như vậy.\n\nCảm ơn bà đã nhanh chóng xử lý việc này.\n\nTrân trọng,\nZack Makoare\nQuản lý Xây dựng, Croydon Construction\n\nEMAIL 2\nGửi: Zack Makoare\nTừ: Sanaa Rahija\nNgày: 16 tháng 8\nChủ đề: RE: Lô hàng quá hạn\n\nKính gửi ông Makoare,\n\nXin thành thật xin lỗi vì đơn hàng 47992 bị chậm trễ. Một máy trong nhà máy của chúng tôi bị trục trặc, gây ra lỗi trong kính cửa sổ. Máy đã được sửa và nhà máy đã quay lại lịch sản xuất bình thường. Chúng tôi đang xử lý gấp đơn hàng của ông và sẽ gửi đi vào ngày mai. Hàng sẽ đến công trường xây dựng phòng khám của ông vào ngày 20/8. Như một cử chỉ thiện chí, chúng tôi sẽ hoàn lại toàn bộ phí vận chuyển.\n\nTrân trọng,\nSanaa Rahija","qs":[{"n":196,"q":"What is suggested on the Web page about Croydon Construction?","qvi":"Trang web gợi ý điều gì về Croydon Construction?","opts":["It recently hired Mr. Kogler.","It has been in business for only a short time.","It is planning to move its headquarters to Christchurch.","It completes projects in countries outside of New Zealand."],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Trang web: “Steve Kogler is our new chief site engineer.” → công ty vừa tuyển ông Kogler. (B) sai: đã hoạt động 25 năm; (C) sai: trụ sở đã ở Christchurch.\n(A) Công ty vừa tuyển ông Kogler\n(B) Công ty mới hoạt động được một thời gian ngắn\n(C) Công ty đang lên kế hoạch chuyển trụ sở đến Christchurch\n(D) Công ty thực hiện dự án ở các nước ngoài New Zealand"},{"n":197,"q":"According to the Web page, what should job applicants do?","qvi":"Theo trang web, người xin việc nên làm gì?","opts":["Visit the company headquarters in person","Attend a career fair","Contact the hiring manager by e-mail","Submit an application online"],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Trang web: “Go to our Jobs page to view open positions and to apply.” → nộp hồ sơ trên trang web (trực tuyến).\n(A) Đến trực tiếp trụ sở công ty\n(B) Tham dự hội chợ việc làm\n(C) Liên hệ quản lý tuyển dụng qua e-mail\n(D) Nộp đơn trực tuyến"},{"n":198,"q":"In the second e-mail, what problem does Ms. Rahija describe?","qvi":"Trong e-mail thứ hai, bà Rahija mô tả vấn đề gì?","opts":["The wrong product was manufactured.","The factory was understaffed.","Some equipment did not operate properly.","Some items in an order broke during transport."],"ans":"C","xp":"Đáp án: (C)\nCăn cứ: E-mail 2: “A machine in our factory malfunctioned, creating flaws in the window glass.” (malfunctioned = did not operate properly).\n(A) Sản xuất sai sản phẩm\n(B) Nhà máy thiếu nhân sự\n(C) Một số thiết bị hoạt động không đúng\n(D) Một số mặt hàng trong đơn bị vỡ khi vận chuyển"},{"n":199,"q":"Where most likely will order 47992 be delivered?","qvi":"Đơn hàng 47992 nhiều khả năng sẽ được giao đến đâu?","opts":["To Grove Road","To Springdale Avenue","To Passerine Way","To Sixth Street"],"ans":"A","xp":"Đáp án: (A)\nCăn cứ: Kết hợp: E-mail 2 – “It will arrive at your medical clinic construction site on 20 August.”; Trang web – “we are building the Willoughby Medical Clinic on Grove Road”.\n(A) Đường Grove Road\n(B) Đại lộ Springdale Avenue\n(C) Đường Passerine Way\n(D) Đường Sixth Street"},{"n":200,"q":"What can be concluded about Mr. Makoare?","qvi":"Có thể kết luận gì về ông Makoare?","opts":["He plans to retire on November 1.","He wants to change his order to a better type of window glass.","He will probably have to postpone a building’s completion date.","He will soon pay a supplier in full."],"ans":"D","xp":"Đáp án: (D)\nCăn cứ: Kết hợp: E-mail 1 – “We shall withhold the balance of payment until the items have been received.”; E-mail 2 – hàng sẽ được gửi ngày mai và đến công trường vào 20/8 → khi nhận hàng, ông sẽ thanh toán nốt phần còn lại cho Wilma Windows. (C) sai: hàng đến 20/8, trước ngày khai trương 1/11.\n(A) Ông dự định nghỉ hưu vào ngày 1/11\n(B) Ông muốn đổi đơn hàng sang loại kính cửa sổ tốt hơn\n(C) Ông có thể sẽ phải hoãn ngày hoàn thành một tòa nhà\n(D) Ông sẽ sớm thanh toán đầy đủ cho nhà cung cấp","note":"Đáp án của key bị thiếu ở câu này (chỉ ghi “Chọn” mà không có chữ cái). Đáp án D được suy ra từ hai e-mail: ông Makoare giữ lại phần tiền còn lại cho đến khi nhận hàng, và hàng sẽ đến ngày 20/8."}]}]}};
